        new Quote { Id = "https://en.wikiquote.org/wiki/Jehoash_of_Israel", Text = "In the thirty-seventh year of Joash king of Judah, Jehoash the son of Jehoahaz became king over Israel in Samaria, and reigned sixteen years. And he did evil in the sight of the Lord. He did not depart from all the sins of Jeroboam the son of Nebat, who made Israel sin, but walked in them.", Author = "Jehoash of Israel" },
