        new Quote { Id = "https://en.wikiquote.org/wiki/Folashade_Abugan", Text = "I am fine now and doing much better. I have started my training. I was formerly in South Africa, but presently I am in Akure, Ondo State. But I hope to be in Lagos next week. By October I will be back to start afresh.", Author = "Folashade Abugan" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Susan_J._Palmer", Text = "New religions are like weeds in our garden. Society’s gardeners will attempt to pull out weeds to make room for cultured plants and familiar religions. However, some weeds may be cherished flowers in other lands, and those deemed invasive might be edible or have healing properties.", Author = "Susan J. Palmer" },
