        new Quote { Id = "https://en.wikiquote.org/wiki/Jill_Pitkeathley%2C_Baroness_Pitkeathley", Text = "It was an easy gig. I think we were mistaken, perhaps, if we thought it would translate into the rather more difficult type of volunteering that we expected people to do.", Author = "Jill Pitkeathley, Baroness Pitkeathley" },
