        new Quote { Id = "https://en.wikiquote.org/wiki/Frannie_L%C3%A9autier", Text = "You get what you measure and if you don’t measure, you won’t be able to achieve results.", Author = "Frannie Léautier" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Franz_Grillparzer", Text = "Let the famous not denounce fame. Far from being empty and meaningless, it fills those it touches with divine power.", Author = "Franz Grillparzer" },
