        new Quote { Id = "https://en.wikiquote.org/wiki/Silence_Is_My_Mother_Tongue", Text = "I didn't choose for my job to be a secret, Nasnet said. It's ironic, though. Society makes it so and then they try to oust you and ostracize you for the secret they have demanded and imposed in the first place.", Author = "Silence Is My Mother Tongue" },
        new Quote { Id = "https://en.wikiquote.org/wiki/James_K._Polk", Text = "Well may the boldest fear and the wisest tremble when incurring responsibilities on which may depend our country's peace and prosperity, and in some degree the hopes and happiness of the whole human family.", Author = "James K. Polk" },
