        new Quote { Id = "https://en.wikiquote.org/wiki/Hansel_%26_Gretel%3A_Witch_Hunters", Text = "The curse of hunger for crawling things. I really hate that one.", Author = "Hansel & Gretel: Witch Hunters" },
