        new Quote { Id = "https://en.wikiquote.org/wiki/John_Taylor_%281578%E2%80%931653%29", Text = "In paper, many a poet now survives", Author = "John Taylor (1578–1653)" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Piano_Sonata_No._2_%28Prokofiev%29", Text = "In appraising my music the critics wrote a good deal of nonsense; for example, the best of them maintained that the finale of Sonata No. 2 made him think of 'a herd of mammoths charging across an Asiatic plateau.'", Author = "Piano Sonata No. 2 (Prokofiev)" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Arusha", Text = "I am happy to be in this town which has become the Geneva of Africa.", Author = "Arusha" },
