        new Quote { Id = "https://en.wikiquote.org/wiki/The_Scarlet_Pimpernel", Text = "The Scarlet Pimpernel works in the dark, and his identity is only known under the solemn oath of secrecy to his immediate followers.", Author = "The Scarlet Pimpernel" },
