        new Quote { Id = "https://en.wikiquote.org/wiki/Natural_law", Text = "It is true that when medieval writers spoke of natural law as being discoverable by reason, they meant that the best human reasoning could discover it, and not, of course, that the results to which any and every individual's reasoning led him was natural law.", Author = "Natural law" },
