        new Quote { Id = "https://en.wikiquote.org/wiki/Virtually_You%3A_The_Dangerous_Powers_of_the_E-Personality", Text = "Saying we have successfully logged off, then, is an expression of seriously wishful thinking: Most of us are never truly offline anymore.", Author = "Virtually You: The Dangerous Powers of the E-Personality" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Margaret_Keane", Text = "It was the eyes that did it. [timid giggle] I liked the way he painted eyes and he liked mine.", Author = "Margaret Keane" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Karen_Fukuhara", Text = "The main issue when it comes to hiring someone from Asia is the language barrier. It's difficult to book someone when they don't speak the language and they can't deliver the lines or even speak to the director. But in terms of Asian-American actresses, we all speak it fluently!", Author = "Karen Fukuhara" },
        new Quote { Id = "https://en.wikiquote.org/wiki/DOA%3A_Dead_or_Alive", Text = "Perfect. Broke another nail.", Author = "DOA: Dead or Alive" },
        new Quote { Id = "https://en.wikiquote.org/wiki/The_Lost_City_%282022_film%29", Text = "This is not a romance novel.", Author = "The Lost City (2022 film)" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Alar_Karis", Text = "Will 2022 be easier? I do not know the answer to this. But I know that together we will make it.", Author = "Alar Karis" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Filthy_Rich_%282020_TV_series%29", Text = "Margaret: Rot in hell.", Author = "Filthy Rich (2020 TV series)" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Franz_Werfel", Text = "Magnify the divine mystery and the holiness of mankind.", Author = "Franz Werfel" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Elsie_MacGill", Text = "I have received many engineering awards, but I hope I will also be remembered as an advocate for the rights of women and children.", Author = "Elsie MacGill" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Victoria_Azarenka", Text = "I do want to have interesting discussions because I’m very professional all the time and I do give insightful answers, but unfortunately, the only that comes up in the media is this one question, and I just feel like I’m wasting my time.", Author = "Victoria Azarenka" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Judy_Youngblood", Text = "To believe in yourself and know who you are when others don't believe in you is the greatest accomplishment; to never give up, to never quit, to have faith and stand your ground. Never change who you are. Love yourself because you have already made it and you are... Somebody.", Author = "Judy Youngblood" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Christiaan_Huygens", Text = "...the power of this line [the cycloid] to measure time.", Author = "Christiaan Huygens" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Robert_Kilwardby", Text = "He was always a good friend of his order. He was conspicuous for his sanctity and care for the poor.", Author = "Robert Kilwardby" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Melissa_Lackey_Oremus", Text = "All of us have done things that we’re not proud of. But we serve a big, forgiving, almighty God.", Author = "Melissa Lackey Oremus" },
        new Quote { Id = "https://en.wikiquote.org/wiki/The_VelociPastor", Text = "I don't believe you. Dinosaurs never existed, and even if they did, I don't transform into one.", Author = "The VelociPastor" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Dimas_Lara_Barbosa", Text = "One of the great tasks of the Church in this century will be the proclamation of an integral anthropology. There are many anthropological reductionisms which have repercussions in lethal practices.", Author = "Dimas Lara Barbosa" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Oda_Gasinzigwa", Text = "The changes in the electoral process and synchronisation would not require a referendum as the electoral law already exists and would be amended accordingly, in agreement with all stakeholders.", Author = "Oda Gasinzigwa" },
        new Quote { Id = "https://en.wikiquote.org/wiki/James_Anthony_Froude", Text = "I cut a hole in my heart and wrote with the blood.", Author = "James Anthony Froude" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Azerbaijani_proverbs", Text = "Balıqçının toruna düşən hər bir canlı onun üçün balıqdır.", Author = "Azerbaijani proverbs" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Paul_J._McAuley", Text = "You can’t hate change. It’s like hating life.", Author = "Paul J. McAuley" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Kristen_Bell", Text = "I, like every other stupid American, assumed the kangaroos would meet us at the airport and they would want to hug us as much as we wanted to hug them. … [In Sydney's zoo] I did find out about the koalas and how eucalyptus makes them high and why they sleep all day. They're little druggies.", Author = "Kristen Bell" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Jim_Stanford", Text = "Everyone has an interest in the economy: in how it functions, how well it functions, and in whose interests it functions.", Author = "Jim Stanford" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Tim_Jenkin", Text = "Getting out was a bit like making your way through a jungle: if you know the way and all the hazards that lie before you the chances of getting through are good; if you know nothing the tendency is to take chances based on intuition, with unknown results.", Author = "Tim Jenkin" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Santadas_Kathiababa", Text = "There will be more work than chanting if you keep the knowledge that God exists in all situations and do all the work with the wisdom of serving God. If you can hold this spiritual wisdom.", Author = "Santadas Kathiababa" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Jackie_Chirchir", Text = "The orders started coming in and this is when I started making jewelry using beads and plastics before introducing metals and wires as raw materials.", Author = "Jackie Chirchir" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Omoyemi_Akerele", Text = "More than ever before, we have to realise that it is important to come together as a community.", Author = "Omoyemi Akerele" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Brian_Kernighan", Text = "Controlling complexity is the essence of computer programming.", Author = "Brian Kernighan" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Mama%27s_Family", Text = "I only drove one time in my life--1946. I started out with a sedan and I came back with a convertible!", Author = "Mama's Family" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Criminal_Minds_%28season_15%29", Text = "David Rossi: Man is not what he thinks he is, he is what he hides. André Malraux", Author = "Criminal Minds (season 15)" },
        new Quote { Id = "https://en.wikiquote.org/wiki/James_Taranto", Text = "If you find yourself despairing about the state of our great country, just think about how unlikely it would have seemed, back in the malaise days of 1979, that Jimmy Carter would one day return to Washington via Reagan Airport.", Author = "James Taranto" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Dance_of_Death_%28novel%29", Text = "What else goes into the ragu, Nonna? If there was any response from the choir invisible, D'Agosta couldn't hear it.", Author = "Dance of Death (novel)" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Milton_A._Rothman", Text = "A scientist looks for a description of the universe in terms of a model that allows him to understand how things work, allows him to predict how things are going to work, and allows him to put together devices that work according to his predictions.", Author = "Milton A. Rothman" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Leah_Stokes", Text = "Most research on opposition to wind energy projects focuses on specific case studies or small geographic areas,", Author = "Leah Stokes" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Plesiosauria", Text = "A snake drawn through the shell of a turtle", Author = "Plesiosauria" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Louis-Siffren-Joseph_de_Salamon", Text = "Gentle as I am now towards every one, it is part of my character never to give way to fear, or to do anything under compulsion.", Author = "Louis-Siffren-Joseph de Salamon" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Harald_V", Text = "We have been given an assignment as a monarchy, and we do as well as we can … We try to be as little populistic as possible. We don't do anything on the spur of the moment to win an opinion poll, or short-term popularity.", Author = "Harald V" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Lloyd_Austin", Text = "If confirmed, I will fight hard to stamp out sexual assault, to rid our ranks of racists and extremists, and to create a climate where everyone fit and willing has the opportunity to serve this country with dignity.", Author = "Lloyd Austin" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Mormonism", Text = "I told the brethren that the Book of Mormon was the most correct of any book on earth, and the keystone of our religion, and a man would get nearer to God by abiding by its precepts, than by any other book.", Author = "Mormonism" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Alastair_Reid_%28poet%29", Text = "... St Andrews, that placid centre of non-learning.", Author = "Alastair Reid (poet)" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Mashrafe_Mortaza", Text = "Mashrafe is ‘a piece of diamond’. People all over the world admire him. I know he will do well both in the cricket field and in Narail.", Author = "Mashrafe Mortaza" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Francis_Beaumont", Text = "She's private to herself and best of knowledgeWhom she'll make so happy as to sigh for.", Author = "Francis Beaumont" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Larry_Niven", Text = "That's the thing about people who think they hate computers … What they really hate are lousy programmers.", Author = "Larry Niven" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Emilio_Gentile", Text = "For Mussolini, syndicalism was the most modern embodiment of the spirit of Marxist doctrine, which he added to the myths of his Nietzschean aristocratic philosophy to reach a socialism of quality rather than quantity.", Author = "Emilio Gentile" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Shulamith_Behr", Text = "Inevitably, the admission of women to the rank of exhibitors upsets the patriarchal hegemony of avant-garde creativity and introduces new relationships of power between people in the group.", Author = "Shulamith Behr" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Nambitha_Mpumlwana", Text = "They may not have as many followers or subscribers as you do, but they know the space", Author = "Nambitha Mpumlwana" },
        new Quote { Id = "https://en.wikiquote.org/wiki/The_Screwy_Truant", Text = "Well, don't want to disappoint you, chum.", Author = "The Screwy Truant" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Wayne_Shorter", Text = "Wayne Shorter, who turns eighty this month, and Sonny Rollins are two of the finest saxophonists living today.", Author = "Wayne Shorter" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Joanna_Trollope", Text = "What I’m trying to do in all these novels is mirror a contemporary preoccupation. I’m not providing any solutions. I’m simply saying: ‘Can we please get the conversation going?’", Author = "Joanna Trollope" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Gerd_von_Rundstedt", Text = "The morale of the troops taking part was astonishingly high at the start of the offensive. They really believed victory was possible - unlike the higher commanders, who knew the facts.", Author = "Gerd von Rundstedt" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Peter_Baldacchino", Text = "The Lord will inspire us how to become creative. If you're sensitive to the needs of others, you will find a way to do something. If you aren't sensitive, you will wash your hands and move on.", Author = "Peter Baldacchino" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Denver", Text = "Stan: Remember when we met in Denver? You said if I'd write you, you would write back.", Author = "Denver" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Star_Wars%3A_The_Clone_Wars_%28season_6%29", Text = "The truth about yourself is the hardest to accept.", Author = "Star Wars: The Clone Wars (season 6)" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Jesse_Helms", Text = "To rob the Negro of his reputation of thinking through a problem in his own fashion is about the same as trying to pretend that he doesn't have a natural instinct for rhythm and for singing and dancing.", Author = "Jesse Helms" },
        new Quote { Id = "https://en.wikiquote.org/wiki/William_Whitehead_%28poet%29", Text = "Yes, I’m in love, I feel it now, And Caelia has undone me, And yet I’ll swear I can’t tell how The pleasing plague stole on me.", Author = "William Whitehead (poet)" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Mohammad_Mustafa", Text = "Until today, we still believe that statehood for Palestinians is the way forward, so we hope that this time around we will be able to achieve that, so that all people in the region can live in security and peace.", Author = "Mohammad Mustafa" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Shlomo_Karhi", Text = "Shameful that a man like that, a former US president, abets propaganda and disseminates things that wound the spirit of Israel’s fighters and its citizens.", Author = "Shlomo Karhi" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Randy_Shilts", Text = "I can only answer that I tried to tell the truth and, if not be objective, at least be fair; history is not served when reporters prize trepidation and propriety over the robust journalistic duty to tell the whole story.", Author = "Randy Shilts" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Jean_Baudrillard", Text = "The real is not only what can be reproduced, but that which is already reproduced, the hyper-real.", Author = "Jean Baudrillard" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Sadiya_Umar_Farouq", Text = "My thoughts and prayers are with the students, their families, and the entire community during this difficult time.", Author = "Sadiya Umar Farouq" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Rose_Aziza", Text = "Nigeria remains a nation sorely betrayed by its people", Author = "Rose Aziza" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Julian_Tuwim", Text = "Everyone kiss my ass.", Author = "Julian Tuwim" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Jo%C3%A3o_Magueijo", Text = "And indeed, if VSL is correct, black holes may have very different properties than we thought. Collapsing stars could have a totally different demise and die a rather eccentric death.", Author = "João Magueijo" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Thiago_Silva", Text = "Messi is a very quick and technically gifted player. When you face him you have to make decisions in an instant. When he approaches you, you have to make the sign of the cross and pray that everything will be alright.", Author = "Thiago Silva" },
        new Quote { Id = "https://en.wikiquote.org/wiki/John_Toto", Text = "I think they should have approached us with the allegations before printing it but they did not and chose to write the falsehoods.", Author = "John Toto" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Jenna_Talackova", Text = "My healthiest transformation was going vegan. … I don’t think words can describe seeing an animal tortured like [in factory farms]. It’s unethical, and it’s something I want to fight against. You are what you eat, and I’d rather be a fruit than a dead, rotting carcass.", Author = "Jenna Talackova" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Mu_Dan", Text = "Countless hearts of gold have been betrayed.A counterfeit coinage circulates,Buying, not a true response,But numb indifference beneath assumed applause.", Author = "Mu Dan" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Bodhinatha_Veylanswami", Text = "From the Hindu perspective, all oflife is sacred, and performing our duty is dhanna. Dhanna is a rich tenn that means way of righteousness, religion and fulfillment of duty. From this lofty view, every deed is a part of our religious practice. Everything we do is an act of worship and faith.", Author = "Bodhinatha Veylanswami" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Snow", Text = "When men were all asleep the snow came flying,In large white flakes falling on the city brown,Stealthily and perpetually settling and loosely lying,Hushing the latest traffic of the drowsy town.", Author = "Snow" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Lydia_Wanyoto", Text = "Turn yourself into a pro by recommitting daily to your lifelong goals and aspirations. Act towards your vision not later or tomorrow but now.", Author = "Lydia Wanyoto" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Morris_Kline", Text = "Henri Poincaré thought the theory of infinite sets a grave malady and pathologic. Later generations, he said in 1908, will regard set theory as a disease from which one has recovered.", Author = "Morris Kline" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Three_Upbuilding_Discourses%2C_1844", Text = "REMEMBER ALSO your Creator in the days of your youth, before the evil days come, and the years draw nigh, when you will say, I have no pleasure in them; Ecclesiastes 12:1 RSV", Author = "Three Upbuilding Discourses, 1844" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Hannah_Webster_Foster", Text = "An unusual sensation possesses my breast — a sensation which I once thought could never pervade it on any occasion whatever. It is pleasure, pleasure, my dear Lucy, on leaving my paternal roof.", Author = "Hannah Webster Foster" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Thomas_Merton", Text = "To say that I am made in the image of God is to say that Love is the reason for my existence, for God is love. Love is my true identity. Selflessness is my true self. Love is my true character. Love is my name.", Author = "Thomas Merton" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Trials_of_faith", Text = "Consider it all joy, my brothers, when you meet with various trials, knowing as you do that this tested quality of your faith produces endurance. But let endurance complete its work, so that you may be complete and sound in all respects, not lacking in anything.", Author = "Trials of faith" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Wanda_Sykes", Text = "I love doing stand-up. ... That's where I feel like I can be free.", Author = "Wanda Sykes" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Suburb", Text = "I guess most people think of the suburb as a place with all the disadvantages of the city, and none of the advantages of the country. And vice versa.", Author = "Suburb" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Ross_Gay", Text = "I was definitely feeling alienated in various ways, and feeling some unarticulated rage and sorrow about a number of things. Once I got introduced to the right poems, I became aware of maybe a way to express those things, articulate them.", Author = "Ross Gay" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Abbie_Hoffman", Text = "The first duty of a revolutionist is to get away with it. The second duty is to eat breakfast. I ain't going.", Author = "Abbie Hoffman" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Eric_Hoffer", Text = "My writing is done in railroad yards while waiting for a freight, in the fields while waiting for a truck, and at noon after lunch. Towns are too distracting.", Author = "Eric Hoffer" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Tegla_Loroupe", Text = "Running was in my blood from the beginning. If God has given you a talent, you have to show it. People told me, 'You won't have children if you run long distances.' It was lies. I wanted to be like the men. If no one gives you encouragement, you have to encourage yourself.", Author = "Tegla Loroupe" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Ellen_Hildreth", Text = "My research explores human vision through the creation of computational models of visual processing and observations from perceptual experiments.", Author = "Ellen Hildreth" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Tintoretto", Text = "Titian, Tintoretto, and Paul Veronese absolutely enchanted me, for they took away all sense of subject. ... It was the poetry of color which I felt, procreative in its nature, giving birth to a thousand things which the eye cannot see, and distinct from their cause.", Author = "Tintoretto" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Abubakar_Muhammad_Zakaria", Text = "The number one benefit of having pure faith and belief is not having the fear of death. Those who have the fear of death should be considered weak in terms of faith.", Author = "Abubakar Muhammad Zakaria" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Nausica%C3%A4_of_the_Valley_of_the_Wind", Text = "A thousand years have passed since the collapse of industrialized civilization. A toxic jungle now spreads, threatening the survival of the last of the human race.", Author = "Nausicaä of the Valley of the Wind" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Chronicle_%28film%29", Text = "Matt! Don't be an idiot! Matt! Matt! You're my ride home!", Author = "Chronicle (film)" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Paul_Scofield", Text = "If you want a title, what's wrong with Mr? If you have always been that, then why lose your title? I have a title, which is the same one that I have always had.But it's not political. I have a CBE, which I accepted very gratefully.", Author = "Paul Scofield" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Emma_Stone", Text = "I am blessed with a great family and great people around me that would be able to kick me in the shins if I ever for one minute got lost up in the clouds. I've been really lucky in that sense.", Author = "Emma Stone" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Patricia_MacCormack", Text = "In terms of carbon footprint, the worst thing you can do is have a child. And it’s the one taboo that nobody wants to speak.", Author = "Patricia MacCormack" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Abigail_Ashley", Text = "I want to encourage everyone to never give up on their dreams. If I can do it, anyone can do it. Just believe in yourself and keep your focus", Author = "Abigail Ashley" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Raashid_Alvi", Text = "The Manmohan Singh government always believed that people in the last line should have the first right to the nation’s resources. And, Indian Muslims are indeed the most backward community.", Author = "Raashid Alvi" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Lean_on_Me", Text = "This is an institution of learning, ladies and gentlemen. If you can't control it, how can you teach? Discipline is not the enemy of enthusiasm!", Author = "Lean on Me" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Wesley_Clark", Text = "I have grown up with guns all my life, but people who like assault weapons they should join the United States Army, we have them.", Author = "Wesley Clark" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Charles_Pratt%2C_1st_Earl_Camden", Text = "A good corroborating chain, if they fail in the last link, the whole will fall to the ground.", Author = "Charles Pratt, 1st Earl Camden" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Dental_implant", Text = "Dental implants are connected to the alveolar bone by osseointegration. Dental implants could be used as a potential bone conduction (BC) hearing assistive device in the mouth.", Author = "Dental implant" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Gerry_Spence", Text = "What the insurance companies have done is to reverse the business so that the public at large insures the insurance companies.", Author = "Gerry Spence" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Quake", Text = "The Mystical Past Comes alive", Author = "Quake" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Richard_Dawkins", Text = "Just because science can't in practice explain things like the love that motivates a poet to write a sonnet, that doesn't mean that religion can. It's a simple and logical fallacy to say, 'If science can't do something, therefore religion can'.", Author = "Richard Dawkins" },
        new Quote { Id = "https://en.wikiquote.org/wiki/James_Dobson", Text = "[P]ain is a marvelous purifier. . . It is not necessary to beat the child into submission; a little bit of pain goes a long way for a young child. However, the spanking should be of sufficient magnitude to cause the child to cry genuinely.", Author = "James Dobson" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Natasha_Sarin", Text = "Every analysis of increased tariffs, both those we have published at The Budget Lab and from others, finds the same thing: tariffs make Americans poorer. American consumers pay the cost of tariffs in the form of higher prices.", Author = "Natasha Sarin" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Gloves", Text = "The use of gloves as a fashion accessory appears to have begun in Europe around the thirteenth century.", Author = "Gloves" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Belinda_Sutton", Text = "Commonwealth of Massachusetts", Author = "Belinda Sutton" },
        new Quote { Id = "https://en.wikiquote.org/wiki/The_Paradine_Case", Text = "She had patience. She could wait. This was, indeed, no ordinary woman.", Author = "The Paradine Case" },
        new Quote { Id = "https://en.wikiquote.org/wiki/John_of_the_Cross", Text = "En una noche oscura, con ansias, en amores inflamada, ¡oh dichosa ventura!, salí sin ser notada, estando ya mi casa sosegada;", Author = "John of the Cross" },
        new Quote { Id = "https://en.wikiquote.org/wiki/The_King_and_I_%281999_film%29", Text = "Someday, you too will know everything.", Author = "The King and I (1999 film)" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Alexander_Berkman", Text = "Man's inhumanity to man is not the last word. The truth lies deeper. It is economic slavery, the savage struggle for a crumb, that has converted mankind into wolves and sheep.", Author = "Alexander Berkman" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Talk_to_Me_%282022_film%29", Text = "Where is she? Oh, my God, oh, my God! Oh, my God, they followed us. Whoever we contacted, they followed us.", Author = "Talk to Me (2022 film)" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Oligarchy", Text = "What about oligarchic cities? Don't you see beggars in them?Almost everyone except the rulers is a beggar there.", Author = "Oligarchy" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Annie_Ernaux", Text = "I can no longer think of any way to change my life except by having a baby. I will never sink lower than that.", Author = "Annie Ernaux" },
