        new Quote { Id = "https://en.wikiquote.org/wiki/Marie_Jos%C3%A9e_Ta_Lou-Smith", Text = "Even if someone say, ‘you will not make it!’, just show them that you can make it because life is not about always giving up. It's about working hard, sacrifice, and making yourself available to push your body to achieve your dreams.", Author = "Marie Josée Ta Lou-Smith" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Jeanne_d%27Arc_Gakuba", Text = "Work Hard! Strive to be a model and for a better education of your children, they will become excellent leaders of this country in the days to come.", Author = "Jeanne d'Arc Gakuba" },
