        new Quote { Id = "https://en.wikiquote.org/wiki/Irene_Mulyagonja", Text = "I am not religious. I believe in God, I draw my strength from God, I belong to a church and prayer group, I do my devotions every day, I take time off to read the word of God and to pray and I believe I get guidance from God.", Author = "Irene Mulyagonja" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Bounfeng_Phoummalaysith", Text = "This special donation is extremely important as it contributes to the Lao government's efforts to maximize the available resources in response to COVID-19 equally among the Lao population and foreign citizens living in Laos.", Author = "Bounfeng Phoummalaysith" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Sara_D%C3%A4britz", Text = "Yes, and I loved playing on a team with boys. I was welcomed at every club, they accepted me and I always felt at home. Playing against boys definitely helped develop my athleticism, my reaction time and my aggressiveness.", Author = "Sara Däbritz" },
