        new Quote { Id = "https://en.wikiquote.org/wiki/Jes%C3%BAs_Tirso_Blanco", Text = "The hope is there thanks to our communities, where faith is so alive that we can see a future through their open attitude to life, to God and the Church.", Author = "Jesús Tirso Blanco" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Onicca_Moloi", Text = "I am passionate about youth development and as a person who has always been an activist, I’ve always been about seeing young people using their gift to empower themselves into bettering their lives to contribute to society.", Author = "Onicca Moloi" },
