        new Quote { Id = "https://en.wikiquote.org/wiki/Meghan_Murphy", Text = "There is, in fact, no place in the world that has managed to make prostitution safe for women, despite efforts to regulate the industry and even to form unions of sorts. Under legalised regimes, trafficking and an illegal industry thrive.", Author = "Meghan Murphy" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Kirsten_Benkendorff", Text = "Our concern extends beyond the survival and protection of the single species, to the entire ecosystem the leaf oysters underpin.", Author = "Kirsten Benkendorff" },
