        new Quote { Id = "https://en.wikiquote.org/wiki/Lazer_Team", Text = "Greetings, O Champion. The Antarian Federation bestows upon you this Suit of Power. A great battle awaits you. The fate of your world lies in your hands. Our enemy is powerful, but a true champion will prevail. Prepare yourself. And good luck, Champion of Earth. Conflict is coming.", Author = "Lazer Team" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Faiza_Jama_Mohamed", Text = "We have seen that more proactive actions from state actors happen when the country’s leader steps up and declares action against gender-based violence.", Author = "Faiza Jama Mohamed" },
