        new Quote { Id = "https://en.wikiquote.org/wiki/William_Tenn", Text = "He knew what the score was—and from here on out, he would be acting on what he knew rather than on what others told him.", Author = "William Tenn" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Bob_Inglis", Text = "The pitchforks and torches can tear down and burn up but they can't build up the institutions and communities so necessary to a stable and prosperous country.", Author = "Bob Inglis" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Barney_Kessel", Text = "One of the finest guitarists to emerge after the death of Charlie Christian, Barney Kessel was a reliable bop soloist throughout his career.", Author = "Barney Kessel" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Sonic_Adventure", Text = "Aw, yeah! This is happenin'!", Author = "Sonic Adventure" },
