        new Quote { Id = "https://en.wikiquote.org/wiki/Colette_Dowling", Text = "Women are brought up to depend on a man and to feel naked and frightened without one. We have been taught to believe that as females we cannot stand alone, that we are too fragile, too delicate, too needful of protection.", Author = "Colette Dowling" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Maria_Troncatti", Text = "Detachment was something that cost me a lot: detachment from my parents, Superiors, town, language, everything; when I boarded the steamer I said goodbye forever. We will see each other again in heaven.", Author = "Maria Troncatti" },
