        new Quote { Id = "https://en.wikiquote.org/wiki/Baltazar_Enrique_Porras_Cardozo", Text = "I remind you that it is not a personal award, it is to let everyone see the need to work for the understanding among all Venezuelans, overcoming all kinds of violence is the only way that will allow us a future of peace and harmony.", Author = "Baltazar Enrique Porras Cardozo" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Vivian_Cheruiyot", Text = "It is great to win gold in my first championships race over 10,000 with a personal best...We were inspired by the marathon girls and we wanted to achieve the same.", Author = "Vivian Cheruiyot" },
