        new Quote { Id = "https://en.wikiquote.org/wiki/Chuene_Morifi", Text = "But I think it's good, you can tell women's football is growing. The coaches are now becoming more wiser in how they approach games. It is good for the fans and it is good for the league.", Author = "Chuene Morifi" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Chief_Temitope_Ajayi", Text = "The more people you invest in the better for you.", Author = "Chief Temitope Ajayi" },
        new Quote { Id = "https://en.wikiquote.org/wiki/John_Stephen_Bazin", Text = "Having been inured for many years to the labors of a missionary life, we feel ready, in spite of our advanced age, to share with you all the hardships' of the ministry. We are ambitious of no distinction. We expect to find in each of you a friend.", Author = "John Stephen Bazin" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Peggy_Moran", Text = "I loved King Kong with Fay Wray. That was one of my favorite pictures. I admired Fay. I thought Fay Wray was so beautiful. I remember later I went to a party and she was there and I sat at her feet and said, 'You were my favorite actress', and I told her how much I worshiped her.", Author = "Peggy Moran" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Frederick_B._Maurice", Text = "As a soldier who has spent a quarter of his life in the study of the science of arms, let me tell you I went into the British Army believing that if you want peace you must prepare for war. I believe now that if you prepare thoroughly and efficiently for war, you get war.", Author = "Frederick B. Maurice" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Colette_Ruhamya", Text = "Des lacs artificiels existent même dans d’autres villes, et une fois que le lac est développé, il doit être attrayant et respectueux de l’environnement tout en développant des activités commerciales relatives aux loisirs des gens", Author = "Colette Ruhamya" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Al-Fatiha", Text = "بِسْمِ ٱللَّهِ ٱلرَّحْمَـٰنِ ٱلرَّحِيمِ ٱلْحَمْدُ لِلَّهِ رَبِّ ٱلْعَـٰلَمِينَ ٱلرَّحْمَـٰنِ ٱلرَّحِيمِ مَـٰلِكِ يَوْمِ ٱلدِّينِ إِيَّاكَ نَعْبُدُ وَإِيَّاكَ نَسْتَعِينُ ٱهْدِنَا ٱلصِّرَٰطَ ٱلْمُسْتَقِيمَ صِرَٰطَ ٱلَّذِينَ أَنْعَمْتَ عَلَيْهِمْ غَيْرِ ٱلْمَغْضُوبِ عَلَيْهِمْ وَلَا ٱلضَّآلِّينَ", Author = "Al-Fatiha" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Keshia_Knight_Pulliam", Text = "No one was there except for the two people to know exactly what happened. All I can speak to is the man that I know and I love.", Author = "Keshia Knight Pulliam" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Damalie_Nagitta-Musoke", Text = "Once the university admits PWDs, it has the duty to give them accessible learning environment and put necessary modifications to facilitate their learning and each ones roles need to be defined.", Author = "Damalie Nagitta-Musoke" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Al-Durr_al-Mukhtar", Text = "And if a man wants to take a concubine and his wife says to him I will kill myself, he is not prohibited [from doing so], because it is a lawful act, but if he abstains to save her grief, he will be rewarded, because of the hadith Whoever sympathises with my community, God will sympathise with him.", Author = "Al-Durr al-Mukhtar" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Michel_Crozier", Text = "Philippe Durance: ... How does one become Michel Crozier?", Author = "Michel Crozier" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Virgil_Miller_Newton", Text = "It was evident that the treatment program’s building was a place where miracles happen.", Author = "Virgil Miller Newton" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Moses", Text = "And she bare him a son, and he called his name Gershom: for he said, I have been a stranger in a strange land.", Author = "Moses" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Gladys_Kipkemoi", Text = "I am not happy about my race because I fell with 2 laps to go. The past 3 years I did not perform at my best but I have been improving a lot recently. I am not saying anything about the Kenyan team for the Olympics, but I will try my best in the rest of the season.", Author = "Gladys Kipkemoi" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Geetanjali_Shree", Text = "...In the writers’ world there is much fun and frolic, and spite and praise...", Author = "Geetanjali Shree" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Anthony_Shaffer_%28writer%29", Text = "Celebrating Christmas without subscribing to Christianity is like watching the Super Bowl without having watched a single regular-season football game all year. Some people watch the Super Bowl exclusively for the commercials; others watch it for the halftime show.", Author = "Anthony Shaffer (writer)" },
        new Quote { Id = "https://en.wikiquote.org/wiki/The_Devil%27s_Own", Text = "All the same, Mr. Fitzsimmoms, if you're not confused, you don't know what's goin' on.", Author = "The Devil's Own" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Helen_Ki%C3%A9non-Kabor%C3%A9", Text = "The approach of the different remains represents a mine of information for the history of ancient iron production where techniques and rites are intertwined.", Author = "Helen Kiénon-Kaboré" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Navid_Afkari", Text = "The evidence is there if the court wants to investigate [the acts of torture].", Author = "Navid Afkari" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Gy%C3%B6rgy_Ligeti", Text = "Now there is no taboo; everything is allowed. But one cannot simply go back to tonality, it’s not the way. We must find a way of neither going back nor continuing the avant-garde. I am in a prison: one wall is the avant-garde, the other wall is the past, and I want to escape.", Author = "György Ligeti" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Boris_Karloff", Text = "You could heave a brick out of the window and hit ten actors who could play my parts. I just happened to be on the right corner at the right time.", Author = "Boris Karloff" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Sviatlana_Tsikhanouskaya", Text = "Personally, I am against deeper integration with Russia because Belarus is a sovereign nation. We want to be independent. We want to find friends and not enemies among other countries.", Author = "Sviatlana Tsikhanouskaya" },
        new Quote { Id = "https://en.wikiquote.org/wiki/J._P._Donleavy", Text = "Rid the mind of knowledge when looking for pleasure. Or start thinking and find a lot of pain.", Author = "J. P. Donleavy" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Julie_Arblaster", Text = "Climate change has already altered the extreme weather we experience in Australia and will continue to do so over the coming years.", Author = "Julie Arblaster" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Festus_Mogae", Text = "I observe in this Forum's founding document, and indeed also in the draft constitution of the regional body to which it is to be affiliated, recognition that journalists and media owners have a common duty to work to the highest professional standards and ethics.", Author = "Festus Mogae" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Michael_E._O%27Hanlon", Text = "War is hell. War is unpredictable, difficult, dangerous—and usually (though not always) worse than its initiators expect when conflict begins. War has features that remain fairly similar from century to century, once you take a reflective perspective and look back on things.", Author = "Michael E. O'Hanlon" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Aisha_Umar", Text = "You have to be content and hard working in life; it gives me great pleasure to spend from my sweat and not having to beg and compromise.", Author = "Aisha Umar" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Larkin_Kerwin", Text = "A scientist has the additional responsibility that comes with being a specialist: explaining science to the public, advising of its usefulness and benefits, and warning of its dangers and disadvantages. This is the responsibility of any specialist.", Author = "Larkin Kerwin" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Bruno_Musar%C3%B2", Text = "Help the Pope to ensure that the Gospel of Jesus reaches all people, especially those who have never heard it. Mission begins at home.", Author = "Bruno Musarò" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Diora_Baird", Text = "Most of the time you're playing the crazy girl or the stripper - always the stripper! I mean, how many strippers can I play. I can do a lap dance phenomenally, and that's not a good sign, because I'm not a stripper.", Author = "Diora Baird" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Ricky_Williams", Text = "I wouldn’t eat a chicken if it dropped dead in front of me holding up a sign that said, ‘Eat Me.’", Author = "Ricky Williams" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Colley_Cibber", Text = "As good be out of the world as out of the fashion.", Author = "Colley Cibber" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Mampho_Tjabane", Text = "We made many promises during the election campaign and we cannot come to you only when we want your votes. We have the mandate to report to you, which is the purpose of today’s gathering.", Author = "Mampho Tjabane" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Hedy_Lamarr", Text = "Any girl can be glamorous. All you have to do is stand still and look stupid.", Author = "Hedy Lamarr" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Akshay_Kumar", Text = "Change cannot come from one politician, it has to come from each one of us and not just for today...it's a gradual process. Let's be responsible & work towards it.", Author = "Akshay Kumar" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Christian_de_Graaff", Text = "I will not resign - De Graaff 21 July 2013", Author = "Christian de Graaff" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Ballerina_%282025_film%29", Text = "They killed my father. This isn't done until they're dead.", Author = "Ballerina (2025 film)" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Fire_Birds", Text = "Mr. Preston, this operation will be a failure if we all die!", Author = "Fire Birds" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Luis_Valdez", Text = "People would call us dirty Mexicans. I remember going to a movie in Reedly where we weren't allowed to sit in the Anglo section. We were told by the ushers to sit with the rest of the Mexicans, because this section was reserved for whites. Those are things you never forget.", Author = "Luis Valdez" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Indigenous_Aryans", Text = "So far as the Rig Veda is concerned, there is not a particle of evidence suggesting the invasion of India by the Aryans from outside India... So far as the testimony of the Vedic literature is concerned, it is against the theory that the original home of the Aryans was outside India.", Author = "Indigenous Aryans" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Judi_Dench", Text = "I think you’ve got to have your feet planted firmly on the ground, especially in this business, and you must not believe things that are said or written about you, because everything gets out of proportion one way or the other.", Author = "Judi Dench" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Biffy_Clyro", Text = "Kill The Old, Torture Their Young", Author = "Biffy Clyro" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Novatus_Rugambwa", Text = "Christianity is not innate or automatic. It is something we receive and learn through our parents, our family, our whanau, our parish community, and later on the wider Catholic community reinforces it.", Author = "Novatus Rugambwa" },
        new Quote { Id = "https://en.wikiquote.org/wiki/John_Faithfull_Fleet", Text = "It is indeed very questionable whether the ancient Hindus ever possessed the true historical sense in the shape of the faculty of putting together genuine history on broad and critical lines.", Author = "John Faithfull Fleet" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Elmer_Davis", Text = "The easiest way to inject a propaganda idea into most people’s minds is to let it go through the medium of an entertainment picture when they do not realize that they are being propagandized.", Author = "Elmer Davis" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Chief_Seattle", Text = "My people are few. They resemble the scattering trees of a storm-swept plain...There was a time when our people covered the land as the waves of a wind-ruffled sea cover its shell-paved floor, but that time long since passed away with the greatness of tribes that are now but a mournful memory.", Author = "Chief Seattle" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Louis_Rukeyser", Text = "Roaming the world as a foreign correspondent for more than a decade, I was able to observe how a variety of vastly different nations organized themselves economically. The inescapable conclusion was that no politician anywhere on the planet has ever actually created a rupee's worth of prosperity.", Author = "Louis Rukeyser" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Ruth_Nanda_Anshen", Text = "There is no depth of life without a way to depth, no truth without a way to truth.", Author = "Ruth Nanda Anshen" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Nevada", Text = "Malenfant had moved his corporation here, out of New York, five years ago. A good place for business, he said. God bless Nevada. Distract the marks with gambling toys and virtual titties while you pick their pockets.", Author = "Nevada" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Per_Bak", Text = "Perhaps our ultimate understanding of scientific topics is measured in terms of our ability to generate metaphoric pictures of what is going on. Maybe understanding is coming up with metaphoric pictures.", Author = "Per Bak" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Bandi_Sanjay_Kumar", Text = "They eat India’s food, breath India’s air and sing songs in praise of Pakistan. They will be kicked out of the country through the surgical strikes.", Author = "Bandi Sanjay Kumar" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Tar%C4%B1k_G%C3%BCnersel", Text = "Life is words in action, literature is action in words.", Author = "Tarık Günersel" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Leon_Kass", Text = "Ancient science had sought knowledge of what things are, to be contemplated as an end in itself satisfying to the knower. In contrast, modern science seeks knowledge of how things work, to be used as a means for the relief and comfort of all humanity, knowers and non-knowers alike.", Author = "Leon Kass" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Dionne_Warwick", Text = "From what I was taught at home, I already knew what I was doing and how to act and how to dress and how to speak. I came from a safe, solid home.", Author = "Dionne Warwick" },
        new Quote { Id = "https://en.wikiquote.org/wiki/The_Dark_Knight_Rises", Text = "There are always people you care about. You just don't realize how much until they're gone. The idea was to be a symbol. Batman could be anybody. That was the point.", Author = "The Dark Knight Rises" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Barfly_%28film%29", Text = "Some people never go crazy. What truly horrible lives they must lead.", Author = "Barfly (film)" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Running", Text = "Run! Run, like the devil's behind us. Run, to where no one can find us. Be my compass.", Author = "Running" },
        new Quote { Id = "https://en.wikiquote.org/wiki/The_King_of_Fighters", Text = "You can't win only by power.", Author = "The King of Fighters" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Bucky_Pizzarelli", Text = "If there's one electric jazz guitarist who can be said to be the living embodiment of the instrument's history, it's Bucky Pizzarelli. He plays rhythm guitar in the spirit of Freddie Green and is noted for his amazing chorded soloing.", Author = "Bucky Pizzarelli" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Little_Rural_Riding_Hood", Text = "Uh-heh! Kissed a cow.", Author = "Little Rural Riding Hood" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Ian_Paisley", Text = "I say to the Dublin government, Mr Faulkner says it's hands across the border to Dublin. I say, if they don't behave themselves in the South, it will be shots across the border!", Author = "Ian Paisley" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Robert_Edouard_Moritz", Text = "Literametrics' may become to philology, what 'Biometrics' has already become to the biological sciences.", Author = "Robert Edouard Moritz" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Shearwater", Text = "Hurts so bad that you know it's not sinning.The funny thing is it's just beginning to feel good.", Author = "Shearwater" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Boston_Public", Text = "Steven Harper: We do not help kids one by one here. Too many of them, too few of us. We serve masses, hoping more of them make it than don't. And our best results, like it or not, come with policy.", Author = "Boston Public" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Saved_by_the_Bell", Text = "Zack: Come on Jessie, there's lots of guys taller than you.\nJessie: Name one.\nZack: Kareem Abdul-Jabbar?", Author = "Saved by the Bell" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Lewis_F._Powell%2C_Jr.", Text = "Preferring members of any one group for no reason other than race or ethnic origin is discrimination for its own sake. This the Constitution forbids.", Author = "Lewis F. Powell, Jr." },
        new Quote { Id = "https://en.wikiquote.org/wiki/P._V._Anvar", Text = "Rahul Gandhi has no right to use the Gandhi surname. He has reached the level of a fourth-class citizen. Can such a person be born in the Nehru family? I have doubts about it. His DNA should be examined.", Author = "P. V. Anvar" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Salmon_P._Chase", Text = "True democracy makes no enquiry about the color of skin, or the place of nativity, whereever it sees man, it recognizes a being endowed by his Creator with original inalienable rights.", Author = "Salmon P. Chase" },
        new Quote { Id = "https://en.wikiquote.org/wiki/English_people", Text = "Of all the races in the Galaxy, only the English could possibly revive the memory of the most horrific wars ever to sunder the Universe and transform it into into what I'm afraid is generally regarded as an incomprehensibly dull and pointless game.", Author = "English people" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Maggie_Benedict", Text = "I didn’t have any fears because my mama said a prayer!", Author = "Maggie Benedict" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Der_Angriff", Text = "Anyone may grumble who is not afraid to go to a concentration camp.", Author = "Der Angriff" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Rehmah_Kasule", Text = "Many times, we do things, but we don't realize how many people we touch. Reflect on this question, Who will cry when you die?", Author = "Rehmah Kasule" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Claire_Karekezi", Text = "Do not let anybody tell you that it is impossible, you can achieve anything.", Author = "Claire Karekezi" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Eleanor_Holmes_Norton", Text = "Congressman David Dreier: Will the gentlewoman yield? Norton: I will not yield, sir! The District of Columbia has spent two hundred and six years yielding!", Author = "Eleanor Holmes Norton" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Gino_Bartali", Text = "Il bene si fa ma non si dice. E certe medaglie si appendono all’anima, non alla giacca.", Author = "Gino Bartali" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Brahmaj%C4%81la_S%C5%ABtra", Text = "The light of wisdom burns brightly in order to shed light on the vacuity of indulgence.", Author = "Brahmajāla Sūtra" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Brenda_Msangi", Text = "For any person to fully rise in leadership or successful journey,they must have three people, a mentor, a coach and a sponsor.", Author = "Brenda Msangi" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Nothando_Vilakazi", Text = "I think showcasing our talent and competing on a global stage will definitely bring positive change into the sport.", Author = "Nothando Vilakazi" },
        new Quote { Id = "https://en.wikiquote.org/wiki/The_Lady_and_the_Monster", Text = "What do I know about the brain itself? Nothing. Can it think? Remember after its body is dead? Could it be made to feel, to hear perhaps, or to express itself in some way? To contact the living?", Author = "The Lady and the Monster" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Wake_in_Fright", Text = "Oh, I'm a bonded slave of the Education Department... I'm a schoolteacher.", Author = "Wake in Fright" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Alive_%281993_film%29", Text = "I saw no color at all in the mountains, just muted patches of black and gray. There was no softness, no life, only rock and snow and ice, and as I looked down into all that rugged wildness, I had to laugh at the arrogance of anyone who had ever thought that human beings have conquered the Earth.", Author = "Alive (1993 film)" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Audrey_Gadzekpo", Text = "We find the political capture of the broadcast media space, in particular, and the increasing concentration of the media in a few hands as worrying for the country’s democracy, and there is the need to address this situation.", Author = "Audrey Gadzekpo" },
        new Quote { Id = "https://en.wikiquote.org/wiki/George_Outram", Text = "I cannot praise the Doctor's eyes; I never saw his glance divine; He always shuts them when he prays, And when he preaches he shuts mine.", Author = "George Outram" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Robert_Plomin", Text = "We now know that DNA differences are the major systematic source of psychological differences between us. Environmental effects are important but what we have learned in recent years is that they are mostly random – unsystematic and unstable – which means that we cannot do much about them.", Author = "Robert Plomin" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Mario_Bardi", Text = "There is nothing in his painting which Sicily cannot explain. (Leonardo Sciascia)", Author = "Mario Bardi" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Douglas_Fraser", Text = "I believe leaders of the business community, with few exceptions, have chosen to wage a one-sided class war today in our country—a war against working people, the unemployed, the poor, the minorities, the very young and the very old, and even many in the middle class of our society.", Author = "Douglas Fraser" },
        new Quote { Id = "https://en.wikiquote.org/wiki/The_Corpse_Vanishes", Text = "You see, our dreams, our minds play strange tricks on us sometimes!", Author = "The Corpse Vanishes" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Janice_Lough", Text = "While bleaching surveys are ongoing, a distinct pattern is emerging, whereby the severity of bleaching declines from north to south.", Author = "Janice Lough" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Varg_Vikernes", Text = "Our purpose is to spread fear and evil.", Author = "Varg Vikernes" },
        new Quote { Id = "https://en.wikiquote.org/wiki/She%27s_All_That", Text = "What is this, some sort of dork outreach program?", Author = "She's All That" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Firestorm_%28film%29", Text = "In case you haven't noticed... we're not firemen.", Author = "Firestorm (film)" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Grace_Coleman", Text = "I wasn't expecting it at all. It was a big surprise", Author = "Grace Coleman" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Amy%27s_Orgasm", Text = "The primary difference between a man and a woman is that man gets his self-esteem when a woman says yes and a women gets hers when she says no.", Author = "Amy's Orgasm" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Ronaldo", Text = "The goal of ending poverty is within reach and everyone can contribute to it by getting involved or supporting organizations that are already working to give the poor a better life... No one should be doomed to a life of poverty, whether by birth or as a consequence of war.", Author = "Ronaldo" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Fast_Times_at_Ridgemont_High", Text = "What are you people, on dope?!", Author = "Fast Times at Ridgemont High" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Martin_Veillette", Text = "I don't think that Quebec can afford a pastoral approach that chooses silence and accommodation at the expense of human life and human dignity. Being discrete hasn’t served Quebec Catholicism.", Author = "Martin Veillette" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Communism_in_India", Text = "Uncompromising opposition to Gandhi and his cherished Hindu convictions meant that communists were cut off in a considerable measure from the mainstream of the patriotic struggle.", Author = "Communism in India" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Sufism", Text = "Their mystical path is the path of Love which ends with the realization of the absolute unification with the Reality.", Author = "Sufism" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Dominica_Dipio", Text = "For us, Africans who are predominantly described as very oral people, the film medium is a very powerful continuation, in a way, of our orality.", Author = "Dominica Dipio" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Abhij%C3%B1%C4%81", Text = "A noble disciple ... possesses confirmed confidence in the Dhamma thus: 'The Dhamma is well expounded by the Blessed One, directly visible, immediate, inviting one to come and see, applicable, to be personally experienced by the wise.'", Author = "Abhijñā" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Aron_Nimzowitsch", Text = "The beauty of a move lies not in its appearance but in the thought behind it.", Author = "Aron Nimzowitsch" },
        new Quote { Id = "https://en.wikiquote.org/wiki/John_Hollander", Text = "Poetry may be written on paper, but it’s an oral art.A good poem satisfies the ear .It creates a story or picture that grabs you.", Author = "John Hollander" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Clifford_Allen%2C_1st_Baron_Allen_of_Hurtwood", Text = "He believed that Christianity stood for the bettering of their fellow men, and the raising of their condition. Were not these the very tenets of Socialism?", Author = "Clifford Allen, 1st Baron Allen of Hurtwood" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Takyiwaa_Manuh", Text = "Ghanaian women have served Ghana, They have served in our communities, our mothers, Because we don’t give them names, the home economist, and the human resource managers in our homes who are able to make magic with often very meagre resources.", Author = "Takyiwaa Manuh" },
        new Quote { Id = "https://en.wikiquote.org/wiki/The_400_Blows", Text = "I have no socks left around these holes.", Author = "The 400 Blows" },
        new Quote { Id = "https://en.wikiquote.org/wiki/The_Million_Dollar_Duck", Text = "Jimmy, don't bother your father with that now. He's got little enough on his mind as it is.", Author = "The Million Dollar Duck" },
        new Quote { Id = "https://en.wikiquote.org/wiki/The_Plague_of_the_Zombies", Text = "I, I find all kinds of witchcraft slightly nauseating and this I find absolutely disgusting.", Author = "The Plague of the Zombies" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Israel_Matseke_Zulu", Text = "I grew up in court. I knew the justice system. Boys will be boys was the judgement and I knew the judgement before it was even given.", Author = "Israel Matseke Zulu" },
        new Quote { Id = "https://en.wikiquote.org/wiki/C%C3%A9cile_Murumunawabo", Text = "We promise that we shall not disappoint you; we shall work hard to be the RPF engine so as to also make our party the country’s engine.", Author = "Cécile Murumunawabo" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Planes_%28film%29", Text = "Time to eat my dust!", Author = "Planes (film)" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Irene_Sabatini", Text = "How my imagination soared — the moon seemed so close that I felt I could reach out and touch it. And then my mind wandered: what are those noises outside?", Author = "Irene Sabatini" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Isaac_Leib_Peretz", Text = "Youth is fair, a graceful stag,Leaping, playing in a park.Age is gray, a toothless hag,Stumbling in the dark.", Author = "Isaac Leib Peretz" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Rabia_Chaudry", Text = "When I decided it was time to get a journalist to look at what I have always held as a wrongful conviction, I did it thinking that reporters can go places most of us can’t. They have ways of tracking down information, getting people to talk, and resources the average person doesn’t.", Author = "Rabia Chaudry" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Edward_Hirsch", Text = "The line is a way of thinking in poetry, by poetry..it paces the poem.", Author = "Edward Hirsch" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Chris_Tonietto", Text = "As we live at a hectic pace and often our prayer time takes a back seat, I took the initiative to call on the Brazilian people to unite in prayer.", Author = "Chris Tonietto" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Princess_Marie_of_Denmark", Text = "The biggest priviledge is that you, as a princess, can create attention about important issues. That I have the opportunity to make a difference.", Author = "Princess Marie of Denmark" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Lady_Mary_Wortley_Montagu", Text = "Let this great maxim be my virtue’s guide,—In part she is to blame that has been tried:He comes too near that comes to be denied.", Author = "Lady Mary Wortley Montagu" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Yevgeniy_Zinkovskiy", Text = "There are no words to express the joy of the entire Catholic community in Kazakhstan at the visit of Pope Francis to our country. What pleases us the most is the fact that even the non-Catholic citizens of the country received the news of the planned trip of the Holy Father with great enthusiasm.", Author = "Yevgeniy Zinkovskiy" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Douglas_Hurd", Text = "Lord Rothschild roamed like a condottiere through Whitehall, laying an ambush here, there breaching some crumbling fortress which had outlived its usefulness... He respected persons occasionally but rarely policies.", Author = "Douglas Hurd" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Jeanine_%C3%81%C3%B1ez", Text = "We want to be a democratic tool of inclusion and unity.", Author = "Jeanine Áñez" },
        new Quote { Id = "https://en.wikiquote.org/wiki/The_Master_of_Petersburg", Text = "‘if you do not kill you are not taken seriously’", Author = "The Master of Petersburg" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Larry_Page", Text = "The Star Trek computer doesn't seem that interesting. They ask it random questions, it thinks for a while. I think we can do better than that.", Author = "Larry Page" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Christine_Todd_Whitman", Text = "When you’re dealing with people who think that Sponge Bob Square Pants is more important than social security, you have a problem.", Author = "Christine Todd Whitman" },
        new Quote { Id = "https://en.wikiquote.org/wiki/August_Wilhelm_Ambros", Text = "Music is become a complaisant and versatile handmaiden, and, since the impossible is demanded of her, she calls up all her strength to perform at least the unusual.", Author = "August Wilhelm Ambros" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Radio_from_Hell", Text = "Goodnight everybody! - Daily Sign-off", Author = "Radio from Hell" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Brad_Pitt", Text = "I keep hearing I'm a crazy party guy … I'm not. I'm boring... At least by party standards.", Author = "Brad Pitt" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Ciiru_Waithaka", Text = "We teach children how to be environmentally conscious by involving them in practical activities.", Author = "Ciiru Waithaka" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Ryan_Zinke", Text = "Without question, our public lands are America’s treasure and are rich in diversity. I fully recognize and appreciate that there are lands that deserve special recognition and are better managed under the John Muir model of wilderness, where man is more of an observer than an active participant.", Author = "Ryan Zinke" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Hound", Text = "His hounds they lie down at his feet,So well they can their master keep.", Author = "Hound" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Axiomatic_system", Text = "A recurring concern has been whether set theory, which speaks of infinite sets, refers to an existing reality, and if so how does one ‘know’ which axioms to accept. It is here that the greatest disparity of opinion exists (and the greatest possibility of using different consistent axiom systems).", Author = "Axiomatic system" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Rio_Ferdinand", Text = "Gary Neville is the club captain but has been injured for the best part of a year now - and Giggsy's taken on the mantlepiece.", Author = "Rio Ferdinand" },
        new Quote { Id = "https://en.wikiquote.org/wiki/David_Rakoff", Text = "It would be peevish and ungracious after being taken to such a lovely supper in this Temple of Food, I know, but I am desperate to ask the question that begs to be posed: Just how fucking good can olive oil get?", Author = "David Rakoff" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Arvo_P%C3%A4rt", Text = "I have discovered that it is enough when a single note is beautifully played.", Author = "Arvo Pärt" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Tale_of_Gudam", Text = "They filled the bronze vessels to the brim. He made the tilimda vessels shine like the holy barge. [...] Many followed Gudam on the streets of Unug. They sat armed before him.", Author = "Tale of Gudam" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Auditions", Text = "I didn't have a problem with rejection, because when you go into an audition, you're rejected already. There are hundreds of other actors. You're behind the eight ball when you go in there.", Author = "Auditions" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Christie_Macaluso", Text = "I was sure it wouldn't be here because it was my home parish, I received all my sacraments here and I expect I will be buried here. This is a densely populated archdiocese and the work is staggering.", Author = "Christie Macaluso" },
        new Quote { Id = "https://en.wikiquote.org/wiki/A%E1%B9%A3a", Text = "You don’t have to wait till you feel the pain. You can start right now. It’s not too late to be grateful.", Author = "Aṣa" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Victoria_Kalima", Text = "The voters trust me, and I have a strong relationship with the traditional leaders in the constituency, so I believe my chances of retaining my seat are high.", Author = "Victoria Kalima" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Silver", Text = "Just for a handful of silver he left us, Just for a riband to stick in his coat.–Found the one gift of which fortune bereft us, Lost all others she sets us devote;They with the gold to give doled him our silver,So much was theirs who so little allowed.", Author = "Silver" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Neale_adaora_nwosu", Text = "I am a woman in STEM and it is my dream that other women build STEM careers too. Adaora on her desire for increased participation of women in STEM", Author = "Neale adaora nwosu" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Intelligence", Text = "Man becomes man only by the intelligence, but he is man only by the heart.", Author = "Intelligence" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Norman_Rockwell", Text = "The View of life I communicate in my pictures excludes the sordid and the ugly. I paint life as I would like it to be. (Somebody once said that I paint the kind of girls your mother would want you to marry.)", Author = "Norman Rockwell" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Job_satisfaction", Text = "The higher we go, the ups and downs at the lower level would gradually fade. If what we do is to be worth while and if we are to get job satisfaction, we have to study more and work hard. The more we work, the stronger the profession would become and grow.", Author = "Job satisfaction" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Neutral_Milk_Hotel", Text = "Someone is waitingTo swallow all the halos out of youAs your face blows through my windowsSending pieces flying all around the room", Author = "Neutral Milk Hotel" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Tsangyang_Gyatso%2C_6th_Dalai_Lama", Text = "Even the stars can be measured,", Author = "Tsangyang Gyatso, 6th Dalai Lama" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Christian_Cage", Text = "I know Jungle Boy, he looked at me like a father figure, he sure did.But here's the thing, Jungle Boy, I never wanted to be your father, I never wanted to be your father figure.You have a father. But your father is dead.", Author = "Christian Cage" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Helen_Kane", Text = "I'm so happy to be a part of this ... era of wonderful nonsense.", Author = "Helen Kane" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Roscoe_Arbuckle", Text = "I don't believe there is any finer mission on earth than just to make people laugh.", Author = "Roscoe Arbuckle" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Telephone_Conversation", Text = "The price seemed reasonable,location Indifferent.The landlady swore she lived Off premises. Nothing remained But self confession. Madam, I warned, I hate a wasted journey–I am African.", Author = "Telephone Conversation" },
        new Quote { Id = "https://en.wikiquote.org/wiki/John_William_Mackail", Text = "Still ... fair, though scarce less old than Rome. Now once again at rest from wandering Across the high Alps and the dreadful sea, In utmost England let it find a home.", Author = "John William Mackail" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Nondumiso_Tembe", Text = "Take the time to develop and study the craft – go to school. Take it seriously as a profession and honour your talent the same way you would if you wanted to become a doctor or a lawyer.", Author = "Nondumiso Tembe" },
        new Quote { Id = "https://en.wikiquote.org/wiki/J%C3%B3n_P%C3%A1ll_Sigmarsson", Text = "There is no point to be alive if you can't do deadlift.", Author = "Jón Páll Sigmarsson" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Varro_Atacinus", Text = "Marmoreo Licinus tumulo jacet, at Cato parvo, Pompeius nullo. Quis putet esse deos?Saxa premunt Licinum, levat altum Fama Catonem, Pompeium tituli. Credimus esse deos.", Author = "Varro Atacinus" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Gina_B._Nahai", Text = "What do you call that moment when we let go of the conviction, albeit illusory, that life will only grow larger? That the horizon will always expand?", Author = "Gina B. Nahai" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Meagan_Good", Text = "It's nothing that I would have ever chosen, and when I realized that it was happening, I was devastated. I was like, 'This is me, Lord. I did everything that I could do to the best of my ability. I don't understand why I did all these things, and then this is my end result.'", Author = "Meagan Good" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Enki", Text = "From sunrise till sunset, may the name of Ezina be praised. People should submit to the yoke of Ezina. Whoever has silver, whoever has jewels, whoever has cattle, whoever has sheep shall take a seat at the gate of whoever has grain, and pass his time there.", Author = "Enki" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Lyna_Khoudri", Text = "Don't you want us to talk about people who bring light, instead?.", Author = "Lyna Khoudri" },
        new Quote { Id = "https://en.wikiquote.org/wiki/How_to_Train_Your_Dragon_%28novel_series%29", Text = "There were dragons when I was a boy.", Author = "How to Train Your Dragon (novel series)" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Roger_Swain", Text = "Doing your own gardening makes you much more aware of food cycles, what it takes to grow it, and what the range of food quality is.", Author = "Roger Swain" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Lordina_Mahama", Text = "I am happy to note that the newly constructed Lordina Foundation Maternity and Children's Ward at the Bole District Hospital has contributed to zero mortality rate recorded in 2023", Author = "Lordina Mahama" },
        new Quote { Id = "https://en.wikiquote.org/wiki/John_J._Whitacre", Text = "All I've done since I've been in Washington has been to sit around and try to look wise, and that's what any man has to do who isn't willing to barter his convictions for political expediency. ... No man who wants to be intellectually honest has any business in Congress.", Author = "John J. Whitacre" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Marigolds", Text = "Her eyes, like marigolds, had sheath’d their light,And canopied in darkness sweetly lay,Till they might open to adorn the day.", Author = "Marigolds" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Dubai_Abulhoul", Text = "...the most important thing is to write for yourself. Publishers can see your passion in the writing, so be true to the story you are trying to tell...", Author = "Dubai Abulhoul" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Jules_Lebreton", Text = "Some historians have pretended that pagan philosophy entirely dominated Justin's Christianity, or at least weakened it. To appreciate fairly this influence it is necessary to remember that in his Apology Justin is seeking above all the points of contact between Hellenism and Christianity.", Author = "Jules Lebreton" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Albert_K._Cohen", Text = "A comparative social science requires a generalized system of concepts which will enable the scientific observer to compare and contrast large bodies of concretely different social phenomena in consistent terms.", Author = "Albert K. Cohen" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Georgina_Onuoha", Text = "Don’t give motivational talks if you live off men.", Author = "Georgina Onuoha" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Bacha_Khan_University_attack", Text = "I'm deeply grieved over the attack, and we are determined and resolved in our commitment to wipe out the menace of terrorism from our homeland.", Author = "Bacha Khan University attack" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Ed_Miliband", Text = "Today a new generation has taken charge of Labour. A new generation that understands the core of change", Author = "Ed Miliband" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Rewilding", Text = "The rewilding of natural ecosystems that fascinates me is not an attempt to restore them to any prior state, but to permit ecological processes to resume.", Author = "Rewilding" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Henry_Paulson", Text = "With Donald Trump as the presumptive presidential nominee, we are witnessing a populist hijacking of one of the United States' great political parties... [R]ooted in ignorance, prejudice, fear and isolationism... This troubles me deeply as a Republican, but it troubles me even more as an American.", Author = "Henry Paulson" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Bruce_Mwape", Text = "I am happy that FIFA is investigating the matter because it will provide an opportunity for my name to be cleared of all the allegations", Author = "Bruce Mwape" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Gustavo_Oscar_Carrara", Text = "The pope continues to look towards the neighborhoods we live in. The people also celebrated this papal support, which goes way beyond supporting me.", Author = "Gustavo Oscar Carrara" },
        new Quote { Id = "https://en.wikiquote.org/wiki/C._T._Studd", Text = "Real Christians revel in desperate ventures for Christ, expecting from God great things and attempting the same with exhilaration.", Author = "C. T. Studd" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Keiko_Bonk", Text = "I come back. The same things are happening.", Author = "Keiko Bonk" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Azie_Tesfai", Text = "I feel honoured to represent black people, sexuality and women.", Author = "Azie Tesfai" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Rufus_Wainwright", Text = "Mowing your lawn is against nature.", Author = "Rufus Wainwright" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Anita_Berber", Text = "If everyone had a body like me, everyone would be walking around naked.", Author = "Anita Berber" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Kristin_Skogen_Lund", Text = "It was shocking at first, we also had a huge drop in our revenues at the beginning which has since picked up very nicely. It’s hard to remember now, but there were a lot of uncertainties back in the spring of last year. We didn’t know how long it would last, how deep we would fall..", Author = "Kristin Skogen Lund" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Norah_Barlow", Text = "I retired but to be perfectly frank I was even busier than before. But it wasn’t as rewarding, I still loved management,", Author = "Norah Barlow" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Old_Bavarian_proverbs", Text = "Die Morgenstund trägt Gold im Mund.", Author = "Old Bavarian proverbs" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Yumi_Sakugawa", Text = "What if instead of drowning in your self- hating thoughts, you spread them apart like cotton candy...", Author = "Yumi Sakugawa" },
        new Quote { Id = "https://en.wikiquote.org/wiki/The_Ruling_Class", Text = "If only I knew then who I was now.", Author = "The Ruling Class" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Jennifer_Bartlett", Text = "I can’t write myself except through reading others’ words.", Author = "Jennifer Bartlett" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Bea_Arthur", Text = "I... was not too happy to suddenly take on this public role thrust upon me. They just assumed I was the Joan of Arc of the women's movement. And I wasn't at all. It put a lot of unnecessary pressure on me.", Author = "Bea Arthur" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Esther_Ndeti", Text = "Startup investment is more than a transfer of funds.", Author = "Esther Ndeti" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Mark_Bray", Text = "Traditional elites were willing to concede many economic demands to liberals over the following decade in exchange for their abandonment of the revolution.", Author = "Mark Bray" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Driven_%282001_film%29", Text = "I got will and I got faith. I believe you can will yourself in anything and do anything. And faith, that is like believing in something, man that's like having a good disease. It's contagious, if you hang around with people who have it you're gonna catch it, and its gonna change your attitude.", Author = "Driven (2001 film)" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Shirley_Chisholm", Text = "The Constitution they wrote was designed to protect the rights of white, male citizens. As there were no black Founding Fathers, there were no founding mothers — a great pity, on both counts. It is not too late to complete the work they left undone. Today, here, we should start to do so.", Author = "Shirley Chisholm" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Stephen_Johnson_Field", Text = "The Constitution deals with substance, not shadows.", Author = "Stephen Johnson Field" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Gandhi_%28film%29", Text = "I was called to the bar in London, and enrolled at the High Court of Chancery. I am, therefore, an attorney. And, since I am in your eyes coloured, I think we can deduce that there is at least one coloured attorney in South Africa.", Author = "Gandhi (film)" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Least_I_Could_Do", Text = "Rayne: It has nothing to do with you. It's me...I don't like you!", Author = "Least I Could Do" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Kajal_Bagwandeen", Text = "When I was younger I didn’t have the guts to pursue my passion, I thought I had to have a stable career since entertainment is mainly on a freelance basis.", Author = "Kajal Bagwandeen" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Thomas_%26_Friends/Season_16", Text = "Charlie: [to Flynn] You look like a big, red wobble on wheels!", Author = "Thomas & Friends/Season 16" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Alison_Bechdel", Text = "Mo: Thanks for the lentils! I have to go home now and rethink my priorities!", Author = "Alison Bechdel" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Naomi_Campbell", Text = "I’ve always believed that you have to share and pass it on. That’s who I am as a person. But I don’t like my kindness to be mistaken for weakness. I do it as initiatives and I do it around the world.…I love working with new young photographers, young designers and a new generation of models.", Author = "Naomi Campbell" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Walk_Off_The_Earth", Text = "R.E.V.O. — Realize Every Victory Outright.", Author = "Walk Off The Earth" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Mad_Monster_Party%3F", Text = "Ah... a lifetime of experimentation capped in one small vial. Now to the final step: The infusion of energy.", Author = "Mad Monster Party?" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Marty_%28film%29", Text = "I've been looking for a girl every Saturday night of my life.", Author = "Marty (film)" },
        new Quote { Id = "https://en.wikiquote.org/wiki/The_Manhattan_Project_%28film%29", Text = "It's the purest plutonium in the universe. Pretty, isn't it?", Author = "The Manhattan Project (film)" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Here_Comes_Honey_Boo_Boo", Text = "Mama: Our hair has always been washed in the kitchen sink.", Author = "Here Comes Honey Boo Boo" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Maliha_Ali_Asghar_Khan", Text = "KP has yet to legislate about early marriages and domestic violence though Punjab and Sindh have already passed laws to stop domestic violence against women,", Author = "Maliha Ali Asghar Khan" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Shreyasi_Singh", Text = "I am with the Narendra Modi in his Atmanirbhar Bharat campaign and I will work hard and to my full capacity. I will work with the BJP and will help the party in making Bihar a developed state.", Author = "Shreyasi Singh" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Rudolf_Peierls", Text = "Born approximation is a familiar and convenient approximation in handling scattering problems. It is adequate, or at least informative, in so many cases that we tend to develop the habit of using its first-order term without always checking the conditions for its applicability.", Author = "Rudolf Peierls" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Roman_Pola%C5%84ski", Text = "Michael, I know she’s a nice girl. She’s too bloody nice. She's supposed to be playing a bitch. Every day I have to make her into a bitch.", Author = "Roman Polański" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Modupe_Ozolua", Text = "I believe we are all here for a purpose, some people will go through life never knowing what their purpose is, while some will. When you are able to identify what your purpose is, it is then you get to enjoy life and live life properly......", Author = "Modupe Ozolua" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Dermot_Pius_Farrell", Text = "Liturgy is very formative of people. Good liturgy can do far more than a talk because you're appealing to the senses.", Author = "Dermot Pius Farrell" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Maneka_Gandhi", Text = "I have not done anything to merit being thrown out. I don't understand why I am being attacked and held personally responsible. I am more loyal to my mother-in-law than even to my mother.", Author = "Maneka Gandhi" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Lorde", Text = "The only thing to contemplate there is this raw force. It's as much terror as beauty. You don't feel welcomed by the natural world – I completely felt like an interloper.", Author = "Lorde" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Zaire", Text = "Zaire is the country that has been the most heavily exploited in the world. That is why farms, ranches, plantations, concessions, commerce, and real estate agencies will be turned over to sons of the country.", Author = "Zaire" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Joseph_Pilates", Text = "I'm not concerned with body building; I'm just trying to make people normal human beings.", Author = "Joseph Pilates" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Josephine_Uwineza", Text = "That’s the main idea so that we can help the women in the village, the women who are less fortunate.", Author = "Josephine Uwineza" },
        new Quote { Id = "https://en.wikiquote.org/wiki/The_Powerpuff_Girls_Movie", Text = "The hobo fomo-ly known as Jojo is nomo! From this day fowo, I shall be known as... MOJO JOJO!", Author = "The Powerpuff Girls Movie" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Peter_Taylor_%28journalist%29", Text = "They killed many civilians, let's not underestimate that, but by and large the IRA tactic was not to deliberately kill civilians - although many civilians, I hasten to add, were killed by the IRA.", Author = "Peter Taylor (journalist)" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Piano_Sonata_No._8_%28Prokofiev%29", Text = "The Eighth is the most expansive of Prokofiev’s sonatas; the first move ment in particular unfolds in an unhurried fashion. The composer initially intended the sonata to consist of four movements, not three.", Author = "Piano Sonata No. 8 (Prokofiev)" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Phumzile_Mgcina", Text = "It's scary, but that is the nature of politics. The history of the organisation motivates us. I believe the ANC has a future and we must fight against the scourge of killings to advance democracy.", Author = "Phumzile Mgcina" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Alengot_Oromait", Text = "Age does not matter, it’s not the age that works, it’s the brain and the knowledge that one has.", Author = "Alengot Oromait" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Thomas_Parnell_%28poet%29", Text = "Still an angel appear to each lover beside,But still be a woman to you.", Author = "Thomas Parnell (poet)" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Tsakana_Nkandih", Text = "I am excited. I have already started preparing for the pageant, besides giving up some of my favourite foods, I am exercising and reading more, trying to get both my body and mind ready for the pageant", Author = "Tsakana Nkandih" },
        new Quote { Id = "https://en.wikiquote.org/wiki/They_Might_Be_Giants_%28film%29", Text = "There are no masses in Virginia City, only individuals whose will for good or bad can bring them to the ends they ought to have. I like that very much.", Author = "They Might Be Giants (film)" },
        new Quote { Id = "https://en.wikiquote.org/wiki/%C5%9Aakra_%28Buddhism%29", Text = "Impermanent, alas, are compounded things.It is the nature of things to arise and pass away.Having come into existence they cease.Their appeasement is the highest bliss.", Author = "Śakra (Buddhism)" },
        new Quote { Id = "https://en.wikiquote.org/wiki/John_Gall", Text = "There is a world of difference, psychologically speaking, between the passive observation that Things Don't Work Out Very Well, and the active, penetrating insight that. Complex Systems Exhibit Unexpected Behavior.", Author = "John Gall" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Colin_Wilson", Text = "I've always believed that a writer has got to remain an outsider. If I was offered anything like the Nobel Prize for Literature, I'd find it an extremely difficult conflict because I'd be basically disinclined to accept.", Author = "Colin Wilson" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Dorothea_Brande", Text = "Act as though it is impossible to fail", Author = "Dorothea Brande" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Mercy_Myra", Text = "Music is my life. And through these last few years, I've experienced various challenges. But through it all I have recognized that music and life are quite similar. Music and life alike is a balance of order, rhythm and harmony.", Author = "Mercy Myra" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Mallika_Sarabhai", Text = "My urge to experiment is not due to laziness or the lack of ability… rather, it opens the scope for creating something new.", Author = "Mallika Sarabhai" },
        new Quote { Id = "https://en.wikiquote.org/wiki/William_Joseph_Kerby", Text = "Economics, ethics, sociology, politics are drawn together by the complex problems of property and each has much to learn from the others.", Author = "William Joseph Kerby" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Richard_Herst", Text = "For there is nothing so hateful to me, as Sin, and that only, for the Love of my Saviour.", Author = "Richard Herst" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Cleopas_Dlamini", Text = "We have said it over and over again that let us vote for women. For women to be in Parliament, someone must vote for them. Means have been made to increase women representation in Parliament, including adding the four women Regional MPs but that is not enough", Author = "Cleopas Dlamini" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Mariel_Zagunis", Text = "The tricky thing about fencing is that there are no secrets. Once you get on the strip, it's almost like I have all the information about you that I could ever want. The same goes for you against me. It comes down to a battle of minds, really.", Author = "Mariel Zagunis" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Benito_Cocchi", Text = "The martyrdom of priests is the result of their conscious choice to share the fate of the flock to the point of extreme sacrifice, when the efforts of mediation between the population and the occupiers, long pursued, lost all chance of success.", Author = "Benito Cocchi" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Savage_Garden", Text = "Memories are to fade. Yeah, they´re designed that way. She doesn´t love you anymore, may be she did long ago.", Author = "Savage Garden" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Owen_Swiny", Text = "The fellow is whimsical and varys his prices every day; and he that has a mind to have any of his works must not seem too fond of it, for he' be ye worse treated for it both in price and painting too.", Author = "Owen Swiny" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Eusebius_of_Caesarea", Text = "He that will deserve the name of a Christian must be such a man as excelleth through the knowledge of Christ and His doctrine; in modesty and righteousness of mind, in constancy of life, in virtuous fortitude, and in maintaining sincere piety toward the one and the only God, who is all in all.", Author = "Eusebius of Caesarea" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Islam_in_Assam", Text = "Few years back the Bengali Muslims from Mymensingh and other areas have settled in Assam. The Assamese Muslims have the enormous responsibility to get them educated in Assamese language, make them proud Assamese and thus strengthen the base of Assamese nationality.", Author = "Islam in Assam" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Mary_Abigail_Dodge", Text = "Whatever an author puts between the two covers of his book is public property; whatever of himself he does not put there is his private property, as much as if he had never written a word.", Author = "Mary Abigail Dodge" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Paula_Boland", Text = "I am deeply honoured and grateful to have been considered for this award. I have been blown away by the wonderful comments I have received since it was announced. I will continue to strive for excellence and contribute towards the industry’s growth and success.", Author = "Paula Boland" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Paul_Simon", Text = "And the war rages on in a land called somewhere And Generals order their men to kill And to fight for a cause they've long ago forgotten While a little cloud weeps on the side of a hill.", Author = "Paul Simon" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Phra_Brahmapundit", Text = "Karuna is most needed to alleviate the suffering of the earth. Karuna moves the hearts of people to alleviate the suffering of beings in need, without any discrimination. Karuna is inseparable from Metta, which translates as loving-kindness and means unconditional love.", Author = "Phra Brahmapundit" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Anne%2C_Princess_Royal", Text = "When I appear in public, people expect me to neigh, grind my teeth, paw the ground, and swish my tail, none of which is easy !", Author = "Anne, Princess Royal" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Tina_Connolly", Text = "Dorie smiled sideways up at her in the manner of children everywhere when they’d gotten away with something.", Author = "Tina Connolly" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Unbelief", Text = "All we have gained then by our unbeliefIs a life of doubt diversified by faith,For one of faith diversified by doubt;We called the chessboard white,— we call it black.", Author = "Unbelief" },
        new Quote { Id = "https://en.wikiquote.org/wiki/The_Clique", Text = "Wait... I lost an earring. NOBODY MOVE!", Author = "The Clique" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Roger_Kimball", Text = "What is not possible is to combine the pursuit of pleasure and the enjoyment of comfort with the characteristic pleasures of a strong mind. If you wish for luxury, you must not nourish the inquisitive instinct.", Author = "Roger Kimball" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Uju_Kennedy-Ohanenye", Text = "Women must be empowered. Without women, There won't be peace. When you empower a woman, you empowered 20 women.", Author = "Uju Kennedy-Ohanenye" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Dele_Odule", Text = "To be a good producer, you need to understand money management because production is a commercial venture.", Author = "Dele Odule" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Sledge_Hammer%21", Text = "Newscaster: Twelve hours have passed since the Mayor's daughter was first reported missing. The police now believe she was kidnapped, or is just very good at hiding.", Author = "Sledge Hammer!" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Robert_J._Marks_II", Text = "AI [artificial intelligence] is like a toddler with a Ph.D.. It’s really smart, but it still needs to be supervised.", Author = "Robert J. Marks II" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Mike_Milbury", Text = "It’s unbelievable that after more than 30 years in the game, pummeling a guy with his loafer will be my legacy. But I guess it's better than having no legacy at all.", Author = "Mike Milbury" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Holstein_Anglia_proverbs", Text = "Nå Regen folgt Sonnenschin.", Author = "Holstein Anglia proverbs" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Spider-Man%3A_Shattered_Dimensions", Text = "Is that a... cartoon pig? (when seeing all of his various incarnations)", Author = "Spider-Man: Shattered Dimensions" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Michal", Text = "David returned to bless his household. But Michal the daughter of Saul came out to meet David, and said, How the king of Israel honored himself today, uncovering himself today before the eyes of his servants’ maids, as any vulgar fellow might shamelessly uncover himself!", Author = "Michal" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Sally_Coulthard", Text = "If you visited your GP and told him you were suffering from a broken heart, what do you think he would prescribe? Antidepressants? Counselling? Or would he just tell you to go home and stop wasting his time?", Author = "Sally Coulthard" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Josephine_Jacobsen", Text = "I may, if I can, sleep; since I must, die. Some say, rise.", Author = "Josephine Jacobsen" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Athanase-Charles-Marie_Charette_de_la_Contrie", Text = "He was, in the nineteenth century, a superb type of the valiant knight, devoted heart and soul to the defence of the pope's temporal sovereignty, and consecrated himself to that cause in the same spirit which actuated the Crusades of the Middle Ages.", Author = "Athanase-Charles-Marie Charette de la Contrie" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Suttree", Text = "In the long arcade of the bus station footfalls come back like laughter. He marches darkly toward his darkly marching shape in the glass of the depot door. His fetch come up from life's other side like an autoscopic hallucination, Suttree and Antisuttree, hand reaching to the hand.", Author = "Suttree" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Dirty_Rotten_Scoundrels_%28musical%29", Text = "What do you want, Freddy!", Author = "Dirty Rotten Scoundrels (musical)" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Joseph_Furphy", Text = "I have just finished writing a full-sized novel; title, Such is Life; scenery, Riverina and northern Vic.; temper, democratic; bias, offensively Australian.", Author = "Joseph Furphy" },
        new Quote { Id = "https://en.wikiquote.org/wiki/The_Two_Gentlemen_of_Verona", Text = "Home-keeping youth have ever homely wits.", Author = "The Two Gentlemen of Verona" },
        new Quote { Id = "https://en.wikiquote.org/wiki/That_%2770s_Show_%28season_7%29", Text = "Eric: Life is like a train. It's bearing down on you and guess what? it's gonna hit you. So you can either start running when it's far off in the distance or you can pull up a chair, crack open a beer and just watch it come.", Author = "That '70s Show (season 7)" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Augustus_De_Morgan", Text = "All existing things upon this earth, which have knowledge of their own existence, possess, some in one degree and some in another, the power of thought, accompanied by perception, which is the awakening of thought by the effects of external objects upon the senses.", Author = "Augustus De Morgan" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Paul_LePage", Text = "Obamacare is forcing the American people to buy health insurance or else pay a tax. Our health care system is moving toward one that rations care and negatively impact millions of Americans.", Author = "Paul LePage" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Teresa_Heinz_Kerry", Text = "I think I can best do my work as a head of a family, as a nurturer, for the family, meaning a nurturer for Pittsburgh, and in that sense what we do here can be applicable in many places in the world.", Author = "Teresa Heinz Kerry" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Persius", Text = "Magister artis ingenique largitorventer.", Author = "Persius" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Kane_Williamson", Text = "I would love to do that. They (Kohli and Root) have been playing brilliantly. I love both. Outstanding cricketers and they have been fantastic for a long period of time. Watching these two bat and perform in the way they have been performing, you can learn a lot.", Author = "Kane Williamson" },
        new Quote { Id = "https://en.wikiquote.org/wiki/John_Dos_Passos", Text = "Humanity has a strange fondness for following processions. Get four men following a banner down the street, and, if that banner is inscribed with rhymes of pleasant optimism, in an hour, all the town will be afoot, ready to march to whatever tune the leaders care to play.", Author = "John Dos Passos" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Ted_2", Text = "Sittin' out here in a public, jerkin' off? Where do you think you are, Red Lobster?", Author = "Ted 2" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Elizabeth_Alexander_%28poet%29", Text = "The story seems to begin with catastrophe but in fact began earlier and is not a tragedy but rather a love story. Perhaps tragedies are only tragedies in the presence of love, which confers meaning to loss. Loss is not felt in the absence of love.", Author = "Elizabeth Alexander (poet)" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Malibu_Shark_Attack", Text = "The Tsunami was just the beginning of the terror.", Author = "Malibu Shark Attack" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Guglielmo_Borghetti", Text = "We need to see God's work as a positive element of this situation. Jesus doesn't have hands, but he has our hands.", Author = "Guglielmo Borghetti" },
        new Quote { Id = "https://en.wikiquote.org/wiki/F._W._de_Klerk", Text = "I'm a Christian. I'm a South African. I'm an Afrikaner. I'm a lawyer. I love my country, and I think that this country has a great future. In that sense of the word, I`m a practical idealist.", Author = "F. W. de Klerk" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Eurotrip", Text = "I saw a gay porno once. I didn't know until halfway in. The girls never came. The girls never came!", Author = "Eurotrip" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Francesco_Maria_Zanotti", Text = "Un metodo può condurre a conseguenze sempre vere, quantunque esso sia forse derivato da un principio falso.", Author = "Francesco Maria Zanotti" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Soup", Text = "To make good soup, the pot must only simmer—'smile,' as the phrase is.", Author = "Soup" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Maryam_Bukar_Hassan", Text = "Pray and be persistent, be really close to Allah and make lots of Du'a, because Allah is amazing and he is the best friend you could ever have.", Author = "Maryam Bukar Hassan" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Lillian_Smith_%28author%29", Text = "She stood at the gate, waiting; behind her the swamp, in front of her Colored Town, beyond it, all Maxwell. Tall and slim and white in the dusk, the girl stood there, hands on the picket gate.", Author = "Lillian Smith (author)" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Nicky_Case", Text = "No medium is particularly better than any other medium for tackling pressing social issues. But, yeah, it really depends on what options I can do. Games happen to be the medium I'm most familiar with.", Author = "Nicky Case" },
        new Quote { Id = "https://en.wikiquote.org/wiki/The_Outlaw_Josey_Wales", Text = "[to bounty hunter] Dyin' ain't much of a livin', boy.", Author = "The Outlaw Josey Wales" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Agostino_Marchetto", Text = "I see Vatican II in continuity with all the ecumenical councils, not as a shooting star, but as part of a constellation, though having some of its own characteristics. Hence, it does not constitute a break, a sort of birth of a new Church.", Author = "Agostino Marchetto" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Jalal_Talabani", Text = "The building of this site would not be possible without the courageous decision by President Bush to liberate Iraq. This building is not only a compound for the embassy but a symbol of the deep friendship between the two peoples of Iraq and America.", Author = "Jalal Talabani" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Morris_Raphael_Cohen", Text = "It has generally been assumed that of two opposing systems of philosophy, e. g., realism and idealism, one only can be true and one must be false; and so philosophers have been hopelessly divided on the question, which is the true one.", Author = "Morris Raphael Cohen" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Robert_Wilson_Lynd", Text = "The art of writing history is the art of emphasizing the significant facts at the expense of the insignificant. And it is the same in every field of knowledge. Knowledge is power only if a man knows what facts not to bother about.", Author = "Robert Wilson Lynd" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Rudolf_Deng_Majak", Text = "We know the human person is spirit and body. And the Lord Jesus also took care of the body when he was in a position to, because through the body we take care of the spirit, through the body we are able to show to our fellow men that we care for them.", Author = "Rudolf Deng Majak" },
        new Quote { Id = "https://en.wikiquote.org/wiki/John_Brooks_%28writer%29", Text = "The Internal Revenue Code of 1954, a document longer than War and Peace, is phrased -inevitably, perhaps- in the sort of jargon that stuns the mind and disheartens the spirit.", Author = "John Brooks (writer)" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Francis_Greenwood_Peabody", Text = "A greater gain to the world...than all the growth of scientific knowledge is the growth of the scientific spirit, with its courage and serenity, its disciplined conscience, its intellectual morality, its habitual response to any disclosure of the truth.", Author = "Francis Greenwood Peabody" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Hillel_the_Younger", Text = "Do not judge your fellow man until you have come into his situation.", Author = "Hillel the Younger" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Robert_H._Jackson", Text = "The office of the lawyer, however poorly filled, is too delicate, personal and confidential to be occupied by a corporation.", Author = "Robert H. Jackson" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Solange_Tetero", Text = "I was motivated to work hard because of the situation back home. I wanted to change the lives of my family members as well as mine, and the only way to achieve that was through hard work and determination.", Author = "Solange Tetero" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Percy_Grainger", Text = "All my life, I have been sickened by everything connected with meat-, fish-, and poultry eating. As a child, I saw apparently nice, kind people wring the necks of fowls, and I thought it foul; and I wondered if I could ever exert any influence to help bring such unworthiness to an end.", Author = "Percy Grainger" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Hel", Text = "Leave the dead to their icy dreams. (Beowulf: The Video Game)", Author = "Hel" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Alash%27le_Abimiku", Text = "If 90 per cent of us are doing the right thing and 10 per cent are not doing it, we won’t get rid of COVID-19. The rise in the number of COVID-19 cases is expected since we are dealing more with community transmission.", Author = "Alash'le Abimiku" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Slap_Shot", Text = "Jesus Christ, what a fuckin' nightmare.", Author = "Slap Shot" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Vasily_Grossman", Text = "The more difficult a man's life had been before the camp, the more furiously he lied. This lie had no practical purpose; it served simply to glorify freedom. How could a man be unhappy outside the camp?", Author = "Vasily Grossman" },
        new Quote { Id = "https://en.wikiquote.org/wiki/William_A._Dembski", Text = "As far as design theorists are concerned, theistic evolution is American evangelicalism's ill-conceived accommodation to Darwinism.", Author = "William A. Dembski" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Black_Panther_Party", Text = "Politics is the art of making the people believe that they are in power, when in fact, they have none", Author = "Black Panther Party" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Hilma_af_Klint", Text = "In a world increasingly skeptical of metaphysical thought, af Klint’s work whispers across centuries. She insists that behind the flower is vibration. Behind the leaf, intention. Behind the pigment, the spirit. And that these things—ephemeral, invisible, inaudible—are the most real of all.", Author = "Hilma af Klint" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Adjany_Costa", Text = "We must always be aware that any conservation space is a range of components: it’s not just about biodiversity, it’s not just about the local communities.", Author = "Adjany Costa" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Legion_of_Super-Heroes", Text = "Secretary: Thank you for calling Eternal Damnation Life Insurance. Like a friendly neighbor, Eternal Damnation is always there.", Author = "Legion of Super-Heroes" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Romagnol_proverbs", Text = "A forza d' fê us fa la pratica.", Author = "Romagnol proverbs" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Bajrang_Dal", Text = "There is nothing wrong in imbibing positive aspects of western culture, but VHP and Bajrang Dal are against obscenity in the name of westernisation. Valentine's Day is one such obscene celebration.", Author = "Bajrang Dal" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Jasmine_Crockett", Text = "When we start talking about things that look like evidence, they wanna act like they blind. They don’t know what this is. These are our national secrets, looks like in the shitter to me.", Author = "Jasmine Crockett" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Abbas_Ka%27bi", Text = "Imam warned that disunity undermines Islam and causes to interrupt Divine blessings. He always reminded that only through unity can the Muslim Ummah achieve progress.", Author = "Abbas Ka'bi" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Rebel_Pepper", Text = "People who live in totalitarian countries experience educational brainwashing and real fear of the government. They are not brave enough to stand out and express different opinions.", Author = "Rebel Pepper" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Sasekani_Manzini", Text = "We appreciate the quick response time from our team and the co-ordination between the emergency health workers who were able to respond as quickly as we expected them to. Had that not happened, we don’t know what the outcome would have been.", Author = "Sasekani Manzini" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Louis_Comfort_Tiffany", Text = "God has given us our talents, not to copy the talents of others, but rather to use our brains and imagination in order to obtain the revelation of true beauty.", Author = "Louis Comfort Tiffany" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Esther_Povitsky", Text = "I like the tone of reality.", Author = "Esther Povitsky" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Hammett", Text = "Why is he tailing me all over town? Does he think I'm pretty or what?", Author = "Hammett" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Maitama_Sule", Text = "I think, we ought to pray for the government and we ought to exercise patience. Let there be constructive criticism. Nigeria is a big country, mark you and it has the potentiality of leading Africa.", Author = "Maitama Sule" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Heath_Ledger", Text = "I'm not good at future planning. I don't plan at all. I don't know what I'm doing tomorrow. I don't have a day planner and I don't have a diary. I completely live in the now, not in the past, not in the future.", Author = "Heath Ledger" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Cars_Toons", Text = "If I am lying, I am cryin'.", Author = "Cars Toons" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Love_%26_Basketball_%28film%29", Text = "I'm a dang on ball player.", Author = "Love & Basketball (film)" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Helen_Asemota", Text = "I am very happy, now more motivated. I feel there is now more to do because people are asking questions. I feel that there is a long road to travel and we have only just started.", Author = "Helen Asemota" },
        new Quote { Id = "https://en.wikiquote.org/wiki/The_Binding_of_Isaac", Text = "Isaac and his mother lived alone in a small house on a hill. Isaac kept to himself, drawing pictures and playing with his toys as his mom watched Christian broadcasts on the television.", Author = "The Binding of Isaac" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Nzambi_Matee", Text = "Plastic waste is everywhere and it’s not going anywhere. The question is what we do with it. What you see as waste, I see as the foundation for something greater.", Author = "Nzambi Matee" },
        new Quote { Id = "https://en.wikiquote.org/wiki/In_the_Heat_of_the_Night_%28film%29", Text = "Now listen, hear me good, Mama. Please. Don't make me have to send you to jail... There's white time in jail and there's colored time in jail. The worst kind of time you can do is colored time.", Author = "In the Heat of the Night (film)" },
        new Quote { Id = "https://en.wikiquote.org/wiki/CSI%3A_Crime_Scene_Investigation_%28season_11%29", Text = "Brass: I know your heart's in the right place, Nick, but the family would be more comfortable if you weren't here. Now, I've been were you are. I know how you feel but sometimes the best thing is to walk away. Okay? That's the right thing.", Author = "CSI: Crime Scene Investigation (season 11)" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Smiley%27s_People", Text = "Two seemingly unconnected events heralded the summons of Mr. George Smiley from his dubious retirement. The first had for its background Paris, and for a season the boiling month of August, when Parisians by tradition abandon their city to the scalding sunshine and the busloads of packaged tourists.", Author = "Smiley's People" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Flirting", Text = "To me? Flirting is just like a sport.", Author = "Flirting" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Zabel_Sibil_Asadour", Text = "There are other tears, bright, clear, untroubled,Shining as the sun, untouched of care.", Author = "Zabel Sibil Asadour" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Hermetica", Text = "They will no longer love this world around us, this incomparable work of God, this glorious structure which He has built...", Author = "Hermetica" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Javier_Mar%C3%ADas", Text = "Life is a very bad novelist. It is chaotic and ludicrous.", Author = "Javier Marías" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Dhul-Nun_al-Misri", Text = "Never think of anyone as inferior to you. Open the inner Eye and you will see the One Glory shining in all creatures.", Author = "Dhul-Nun al-Misri" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Prithvi_Narayan_Shah", Text = "If the citizens are wealthy, the country is strong. The King's storehouse is his people.", Author = "Prithvi Narayan Shah" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Goblins_%28webcomic%29", Text = "Young-and-Beautiful: For countless generations we have done things a certain way. We can't just do everything differently now because it makes sense.", Author = "Goblins (webcomic)" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Carlotta_Gilli", Text = "Swimming has given me a path: giving up is never an option.", Author = "Carlotta Gilli" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Pain", Text = "Sunny days wouldn't be special if it wasn't for rain; joy wouldn't feel so good if it wasn't for pain.", Author = "Pain" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Anita_Hill", Text = "The Supreme Court is only as good as the people who are on it.", Author = "Anita Hill" },
        new Quote { Id = "https://en.wikiquote.org/wiki/University_of_Michigan", Text = "An uncommon education for the common man.", Author = "University of Michigan" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Javier_P%C3%A9rez_de_Cu%C3%A9llar", Text = "It is ironic that the accumulation of arms is one of the few expanding industries in a period of economic depression and gloom.", Author = "Javier Pérez de Cuéllar" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Major_Payne", Text = "Know this: Killing is my business, ladies; and business is GOOD!", Author = "Major Payne" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Ryszard_Kasyna", Text = "We want to give back memory, we want to give back dignity to the victims of the crimes in Chojnice.", Author = "Ryszard Kasyna" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Choir", Text = "I guess I originally got the bug for performing when I was in choirs and school stuff and all that. I don't know when. I guess I decided to do it because a lot of people said I was good, and I liked the attention.", Author = "Choir" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Ottok%C3%A1r_Proh%C3%A1szka", Text = "The kingdom of heaven consists of real, confident, and loving union with God, in the cleaving of our souls to Him and their rest in Him. We have to assert this fact and convince ourselves of it in the face of everything which threatens to trouble, oppress, or overwhelm us.", Author = "Ottokár Prohászka" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Chulalongkorn", Text = "Be humble and avoid vengefulness, he advised. Being a king means not to be wealthy. It means not bullying others.", Author = "Chulalongkorn" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Enoch_Crowder", Text = "Arthur MacArthur was the most flamboyantly egotistical man I had ever seen, until I met his son.", Author = "Enoch Crowder" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Coonskin_%28film%29", Text = "I'm tired of trying to segregate, integrate, and masturbate anymore!", Author = "Coonskin (film)" },
        new Quote { Id = "https://en.wikiquote.org/wiki/John_of_Kronstadt", Text = "Adam and Eve ruined themselves through gluttony.", Author = "John of Kronstadt" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Wuthering_Heights_%281939_film%29", Text = "I want to crawl to her feet, whimper to be forgiven, for loving me, for needing her more than my own life, for belonging to her more than my own soul.", Author = "Wuthering Heights (1939 film)" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Eric_A._Havelock", Text = "A scholar like myself who is not a Sinologist and yet ventures the proposition that Chinese languages should be rewritten in the Greek alphabet (or Romanized, to use the current term) is treading on uncharted territory (for him) and does so at his peril.", Author = "Eric A. Havelock" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Chris_Walla", Text = "My favorite sport is Scrabble.", Author = "Chris Walla" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Robert_John_Brennan", Text = "I ask all to continue to pray for the unborn who died, for all those who have experienced the pain of abortion, and for those who cannot understand our divine and steadfast calling to champion this cause.", Author = "Robert John Brennan" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Yes", Text = "Yes is the answer and you know that for sure. Yes is surrender, you got to let it, you got to let it go…", Author = "Yes" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Jill_Farrant", Text = "In terms of what I want to do, Africa, Africa, Africa. We are a continent that’s reliant on rain for our crops: we are already a poor continent so we cannot put in a lot of irrigation.", Author = "Jill Farrant" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Harriet_Beecher_Stowe", Text = "What makes saintliness in my view, as distinguished from ordinary goodness, is a certain quality of magnanimity and greatness of soul that brings life within the circle of the heroic.", Author = "Harriet Beecher Stowe" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Theodore_Gray", Text = "And so it is that we come to the end of our journey through the periodic table not with a bang, but with a committee.", Author = "Theodore Gray" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Bill_Bryson", Text = "I come from Des Moines. Somebody had to.", Author = "Bill Bryson" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Effeminacy", Text = "In a slothfull peace both courages will effeminate, and manners corrupt.", Author = "Effeminacy" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Gabrielle_Anwar", Text = "I just have a series of memorable moments that are strung together which makes me very happy, because otherwise I’d just be hoping to relive the lost memorable moment. But I’m actually looking forward to going back to work. It’s something I haven’t often said.", Author = "Gabrielle Anwar" },
        new Quote { Id = "https://en.wikiquote.org/wiki/My_Life_In_Ruins", Text = "[to Irv] You’re not funny. Stop trying.", Author = "My Life In Ruins" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Juanita_Christensen", Text = "Employees are our number one asset, and their concerns are valid, so I'm taking a very strategic approach to address items from the DEOCS survey perspective", Author = "Juanita Christensen" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Alessandro_Di_Battista", Text = "[...] we know perfectly well that war exists solely and exclusively for economic interests, which are always the same, and that it is always a small number of people who determine the choices of entire populations!", Author = "Alessandro Di Battista" },
        new Quote { Id = "https://en.wikiquote.org/wiki/The_Big_Hit", Text = "Well ain't that a bitch... All I wanted to do was to sail my boat, man, you know? Navigate by the stars, see dolphins race alongside, you know, maybe even kill a few of them.", Author = "The Big Hit" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Mark_A._Gabriel", Text = "The root of Islamic terrorism is the fundamentalist application of the Quran and the life of Muhammad.", Author = "Mark A. Gabriel" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Marriage_and_Morals", Text = "Love as a relation between men and women was ruined by the desire to make sure of the legitimacy of children.", Author = "Marriage and Morals" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Adaora_Lily_Ulasi", Text = "Make u no worry. That be how life be. Sometimes it go up, up, up, and sometimes it come down, down, down. When it go up, you get many friends. But when it come down, your friends run away.", Author = "Adaora Lily Ulasi" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Ben_Garrison", Text = "I disagree with him on some of the issues. But when he came out and said he’s willing to audit the Federal Reserve, I said, He’s worth supporting, especially since he’s not afraid to be politically incorrect. That’s a huge breath of fresh air, I wish he would renounce his support for the NSA.", Author = "Ben Garrison" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Muslim_population_growth", Text = "The birth-rate delivers 96% of the region's Muslim population growth on the continent, which is much higher in comparison to African population growth rates in general.", Author = "Muslim population growth" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Rose_Kabuye", Text = "I am innocent and ready to prove it.", Author = "Rose Kabuye" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Sandrine_Umutoni", Text = "Rwanda’s commitment to promoting gender equality can be seen in policies that ensure women’s representation at various levels of decision-making across different institutions, ranging from business to leadership and judiciary.", Author = "Sandrine Umutoni" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Lewis_Hamilton", Text = "Sure every driver has his value and you want to be respected but again money is not something that drives me.", Author = "Lewis Hamilton" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Kountry_Wayne", Text = "Expect the unexpected. It's like talking to your family members, and making everybody laugh", Author = "Kountry Wayne" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Brigid_Brophy", Text = "Reason can always disarm the irrational. If reason finds itself to be irrational, it can disarm it; and if one finds reason and discovers that eating animals is immoral, unnecessary, and done largely for superstitious reasons, then one is delivered from the compulsion to do it.", Author = "Brigid Brophy" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Arpeggio", Text = "More than 40 years after the release of Van Halen, the opening riff in Ain’t Talkin’ ’Bout Love - an arpeggiated Am-F-G5 passage played with palm-muted downstrokes - is still a favorite among beginning and intermediate pickers.", Author = "Arpeggio" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Percy_Cerutty", Text = "To become great, whether an artist, a musician, a writer, a philosopher or creator or scientist, even as one great in sport, the secret lies, assuming there is some native ability in the first place, in one factor above all others – emotion.", Author = "Percy Cerutty" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Thomas_Savundaranayagam", Text = "In the Catholic Church, it is not like politics. When we accept a task, our main duty is to continue what our predecessors did.", Author = "Thomas Savundaranayagam" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Mark_Satin", Text = "Slowly at first, and now in growing numbers, from Maine to Alabama to California, from ghettos, suburbs and schools, young Americans are coming to Canada to resist the draft.", Author = "Mark Satin" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Giles_Fletcher_the_Elder", Text = "Both poles we burnt, whereon the world doeth turne,The rownd of heaven, from earth unto the skies:And nowe the seas we both intend to burne:I with my bowe, and Licia with her eyes.", Author = "Giles Fletcher the Elder" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Drop_Dead_Gorgeous", Text = "Oh no, my mom never kept a secret of the fact my dad chose his career over us. What was it she used to say? Once a carnie, always a carnie. Mom still cries every time she sees a tilt-a-whirl or a fat lady in a tube top.", Author = "Drop Dead Gorgeous" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Woman_in_the_Dark_%281934_film%29", Text = "One thing I like about bananas is that they got no bones in them.", Author = "Woman in the Dark (1934 film)" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Kiran_Nepali", Text = "A politician can deliver an hour-long speech to make a point. Music and art have the potential to make that impact in seconds.", Author = "Kiran Nepali" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Looney_Tunes%3A_Back_in_Action_%28video_game%29", Text = "Hey, another five cents!", Author = "Looney Tunes: Back in Action (video game)" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Brian_T._Carroll", Text = "The long game for Christians in the public square is a big loss if more people don't get out there and proclaim the Gospel message.", Author = "Brian T. Carroll" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Michael_Kinsley", Text = "Conservatives are always looking for converts, whereas liberals are always looking for heretics.", Author = "Michael Kinsley" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Oldboy_%282003_film%29", Text = "When the melody turns on, gas comes out. When the gas comes out, I fall asleep. I found out later it's the same Valium gas the Russians used on those Chechen terrorists.", Author = "Oldboy (2003 film)" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Captain_America_%281990_film%29", Text = "Gee whiz, we gotta get going, Mr. President.", Author = "Captain America (1990 film)" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Salvador_Sobral", Text = "We live in a world of disposable music; fast-food music without any content... Music is not fireworks, music is feeling. So let's try to change this and bring music back which is really what matters.", Author = "Salvador Sobral" },
        new Quote { Id = "https://en.wikiquote.org/wiki/A_Cure_for_Wellness", Text = "Do you know what the cure for the human condition is? Disease. Because that's the only way one could hope for a cure.", Author = "A Cure for Wellness" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Langston_Hughes", Text = "I, too, sing America. I am the darker brother. They send me to eat in the kitchen When company comes, But I laugh, And eat well, And grow strong.", Author = "Langston Hughes" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Chevrolet_Corvette", Text = "I do things my way. Vipe or Vette; I tear up the highway.", Author = "Chevrolet Corvette" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Hard_Candy_%28film%29", Text = "I shouldn't have teased you like that. I shouldn't have let you think there was a way out of this.", Author = "Hard Candy (film)" },
