        new Quote { Id = "https://en.wikiquote.org/wiki/James_Clackson", Text = "In summary the Indo-Europeanist’s data and method do not allow the question ‘When was PIE spoken?’ to be answered in any really meaningful or helpful way.", Author = "James Clackson" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Edmond_Halley", Text = "Wherefore, if, according to what we have already said, it should return again about the year 1758, candid posterity will not refuse to acknowledge that this was first discovered by an Englishman.", Author = "Edmond Halley" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Creature_Commandos_%28TV_series%29", Text = "Amanda Walller: Congress said we can't use human prisoners. These assholes aren't human.", Author = "Creature Commandos (TV series)" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Kurt_Warner", Text = "Whether I'm a Super Bowl Champion or a regular guy stocking groceries at the Hy-Vee, sharing my faith and glorifying Jesus is the central focus of my time on this earth.", Author = "Kurt Warner" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Maryn_McKenna", Text = "We stand today on the threshold of the post-antibiotic era, in the earliest days of a time when simple infections ... will kill people once again. In fact, they already are. People are dying of infections again, because of a phenomenon called antibiotic resistance.", Author = "Maryn McKenna" },
        new Quote { Id = "https://en.wikiquote.org/wiki/South_Park", Text = "Screw you guys, I’m going home! and Respect my authority! by Eric Cartman", Author = "South Park" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Ursula_Owusu", Text = "I'm the best candidate, and I will win the primaries come January 27th, My party has decided to present me again because there is no reason to change me for any new person.", Author = "Ursula Owusu" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Patricia_Joan_Vinnicombe", Text = "I would altogether talk to thee, while my thinking.", Author = "Patricia Joan Vinnicombe" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Don%27t_Be_a_Sucker%21", Text = "In this country we have no other people, we are American people, all of us.", Author = "Don't Be a Sucker!" },
        new Quote { Id = "https://en.wikiquote.org/wiki/M._H._Abrams", Text = "John Updike is always fun. And one of my former students, Tom Pynchon. I like to read Archie Ammons, my great friend. And Harold Bloom, another former student.", Author = "M. H. Abrams" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Charlie_Parker", Text = "I realized by using the high notes of the chords as a melodic line, and by the right harmonic progression, I could play what I heard inside me. That's when I was born.", Author = "Charlie Parker" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Santiago_Ram%C3%B3n_y_Cajal", Text = "Any man could, if he were so inclined, be the sculptor of his own brain ( p. xv).", Author = "Santiago Ramón y Cajal" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Spider-Man%3A_Far_from_Home", Text = "The world needs the next Iron Man.", Author = "Spider-Man: Far from Home" },
        new Quote { Id = "https://en.wikiquote.org/wiki/A_History_of_European_Thought_in_the_Nineteenth_Century", Text = "The object of the book is philosophical, in the sense now accepted by many and by divergent schools—i.e., it desires to contribute something towards a unification of thought.", Author = "A History of European Thought in the Nineteenth Century" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Bobby_Jindal", Text = "This is a serious storm that has caused serious damage in our state … We're pleased we haven't seen breaches in the levees. We're pleased we haven't seen major flooding in New Orleans or the places that flooded before. But there are serious challenges.", Author = "Bobby Jindal" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Laura_Esquivel", Text = "As a very young girl, I understood that the interior activities of the home are as significant as the exterior activities of society.", Author = "Laura Esquivel" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Taiwo_Hassan", Text = "Remember, once a boxer always a boxer.", Author = "Taiwo Hassan" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Shenzhen", Text = "Shenzhen is shouldering the weight of innovation to achieve Chinese tech breakthroughs in strategic industries while propelling the entire country up the value chain to hedge against economic headwinds, punctuated by four D’s – debt, deflation, de-risking and demographics.", Author = "Shenzhen" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Lilly_Adong", Text = "Why is an entity, in which the government holds the majority share, reducing staff salaries at a time when journalists are playing a crucial role in serving the nation during the lockdown? There is an urgent call for government intervention to protect these workers.", Author = "Lilly Adong" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Abbott_Eliot_Kittredge", Text = "Oh! for this baptism of fire! when every spoken word for Jesus shall be a thunderbolt, and every prayer shall bring forth a mighty flood.", Author = "Abbott Eliot Kittredge" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Serenity", Text = "As you cannot have a sweet and wholesome abode unless you admit the air and sunshine freely into your rooms, so a strong body and a bright, happy, or serene countenance can only result from the free admittance into the mind of thoughts of joy and good will and serenity.", Author = "Serenity" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Revenge_of_the_Nerds", Text = "We've got bush! We've got bush!", Author = "Revenge of the Nerds" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Arthur_Kekewich", Text = "Public policy does not admit of definition and is not easily explained. It is a variable quantity; it must vary and does vary with the habits, capacities, and opportunities of the public.", Author = "Arthur Kekewich" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Amina_Mohamed", Text = "I laud the commitment of all Zimbabweans to ensuring that Election Day proceeded largely peacefully and urge all political parties and their supporters to honour this pledge in the coming days and to use available legal means for conflict resolution.", Author = "Amina Mohamed" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Wanda_Toscanini", Text = "You married an angel and a devil mixed together there, mrs. Horowitz.", Author = "Wanda Toscanini" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Westminster_Assembly", Text = "Q. What is the chief end of man? A. Man's chief end is to glorify God, and to enjoy him for ever.", Author = "Westminster Assembly" },
        new Quote { Id = "https://en.wikiquote.org/wiki/The_Cruel_Sea_%281953_film%29", Text = "This is a story of the Battle of the Atlantic, the story of an ocean, two ships and a handful of men. The men are the heroes. The heroines are the ships. The only villain is the sea—the cruel sea—that man has made more cruel.", Author = "The Cruel Sea (1953 film)" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Dagmawit_Moges", Text = "As a passionate African leader, I am committed to driving positive change, fostering unity, and unlocking opportunities for inclusive growth.", Author = "Dagmawit Moges" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Sarah_Ladipo_Manyika", Text = "A book reads us as much as we read a book.", Author = "Sarah Ladipo Manyika" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Sarah_Perkins-Kirkpatrick", Text = "Climate change doesn’t tell the whole story, as extreme rainfall can occur for a variety of reasons.", Author = "Sarah Perkins-Kirkpatrick" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Margaret_Wheatley", Text = "In organizations, real power and energy is generated through relationships. The patterns of relationships and the capacities to form them are more important than tasks, functions, roles, and positions.", Author = "Margaret Wheatley" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Critical_phenomena", Text = "The mathematical theory of critical phenomena is currently undergoing intense development. Intertwined with the science of phase transitions, it draws on ideas from probability theory and statistical physics.", Author = "Critical phenomena" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Elizabeth_Bowes-Lyon", Text = "The children won't go without me. I won't leave the King. And the King will never leave.", Author = "Elizabeth Bowes-Lyon" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Zig_Ziglar", Text = "You can get everything in life you want if you will just help enough other people get what they want.", Author = "Zig Ziglar" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Deborah_Owusu-Bonsu", Text = "Whenever I am in a relationship, I go all out for the person. I always put the people I love ahead of my needs. When I am in a relationship, I invest all my energy and resources which ends up draining me and slowing me down. I get turned off when I realize the affection is only one-sided.", Author = "Deborah Owusu-Bonsu" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Mary_of_Teck", Text = "Really! This might be Roumania!", Author = "Mary of Teck" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Jimmy_Wales", Text = "What if we could get everyone in the world together to record what they know in one place?", Author = "Jimmy Wales" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Carlo_Carr%C3%A0", Text = "Constructions of a-rhythmical forms, the clash between concrete and abstract forms.. ..The acute angle is passionate and dynamic, expressing will and a penetrating force.", Author = "Carlo Carrà" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Votian_proverbs", Text = "Ikä ühs on omā onnē pällä seppä.", Author = "Votian proverbs" },
        new Quote { Id = "https://en.wikiquote.org/wiki/The_Hidden_Hand_%281942_film%29", Text = "Detective: I almost remembered where I'd seen you before, and it wasn't London.\nJohn Channing: Are you sure about that?\nDetective: Well it might've been London, except I was never there.", Author = "The Hidden Hand (1942 film)" },
        new Quote { Id = "https://en.wikiquote.org/wiki/What%27s_Up%2C_Doc%3F_%281950_film%29", Text = "[first lines; answering the phone] Eh, start talking. It's your nickel.", Author = "What's Up, Doc? (1950 film)" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Lieke_Martens", Text = "The most important thing is that little kids, little girls have a dream they can accomplish now.", Author = "Lieke Martens" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Liaquat_Ali_Khan", Text = "Allah, save this country! Pakistan zindabad!", Author = "Liaquat Ali Khan" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Fenrir", Text = "Fenrir shall with impious toothSlay the sire of rolling years:Vithar shall avenge his fall,And, struggling with the shaggy wolf,Shall cleave his cold and gory jaw.", Author = "Fenrir" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Stanislav_Grof", Text = "It is essential that we raise the image of sex, which is currently seen as a purely biological affair and often portrayed in its worst manifestations, to that of a spiritually based activity", Author = "Stanislav Grof" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Manon_des_Sources_%281986_film%29", Text = "There's no gold here. It's Jurassic cretaceous from the second Quaternary era.", Author = "Manon des Sources (1986 film)" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Margaret_Muthwii", Text = "Great institutions are built through vision, hard work and dedication. That is what I am driven by. In leadership, you rarely look down upon a person because they are either a man or woman. Both do complement each other.", Author = "Margaret Muthwii" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Confession", Text = "The confession of evil works is the first beginning of good works.", Author = "Confession" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Anthony_Pilla", Text = "As the parish goes, so goes the faith of the people.", Author = "Anthony Pilla" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Margo_Glantz", Text = "Zoom and other outlets deform our images, making us lose our actual bodies, and with the possibility of contacting each other this way—we become holograms, or ghosts like Justine from Bioy Casares’s great novel, The Invention of Morel.", Author = "Margo Glantz" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Jessica_Francis_Kane", Text = "I write what I am interested in, and hope it will find an audience. I don’t know that it would make a lot of sense to do it the other way around.", Author = "Jessica Francis Kane" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Bugs_Bunny_Builders", Text = "Bugs Bunny: [the first words of the series] Beautiful day for hopping.", Author = "Bugs Bunny Builders" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Bose_Ogulu", Text = "GOD and my father, Benson Idonije. My father is the best parent I know and he has managed to live according to the values he taught and still believes in.", Author = "Bose Ogulu" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Emma_Mbua", Text = "The species was previously thought not to exist in Kenya, so this discovery has thrust Kenya once again into the limelight as the home of one of the most important archaeological discovered. That A. Afarensis existed in Highlands as well as lowland Savannah shows that it was very adaptable", Author = "Emma Mbua" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Perth_%28film%29", Text = "I am a very simple man.", Author = "Perth (film)" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Afsar_Khan_%28politician%29", Text = "If she comes to the city again we will kill her, added Muqtada Afsar Khan, one of the three MIM legislators who attacked the writer at a book release function at the Press Club.", Author = "Afsar Khan (politician)" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Athenagoras_of_Syracuse", Text = "If a man does not strike first, he will be the first struck.", Author = "Athenagoras of Syracuse" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Optimism", Text = "The optimism of the Left was created and maintained by a strong feeling: admiration for the power of reason, certainty that the application of science to industry would revolu­tionise the order of human society and the condition of its individual members.", Author = "Optimism" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Becky_Lynch", Text = "But the only thing that's ending on Saturday night is your five-hundred-day title reign when I become the Raw Women's Champion.", Author = "Becky Lynch" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Hansel_and_Gretel_%282002_film%29", Text = "Off like a light, into the light!", Author = "Hansel and Gretel (2002 film)" },
        new Quote { Id = "https://en.wikiquote.org/wiki/The_Great_Instauration", Text = "While men are occupied in admiring and applauding the false powers of the mind, they pass by and throw away those true powers which, if it be supplied with the proper aids and can itself be content to wait upon nature instead of vainly affecting to overrule her, are within its reach.", Author = "The Great Instauration" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Kyrylo_Budanov", Text = "Sometimes it’s necessary for me to be with my people to motivate them. I’m not taking excuses for why someone can’t do something. That’s why the task will always be accomplished.", Author = "Kyrylo Budanov" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Bruce_Schneier", Text = "Anyone, from the most clueless amateur to the best cryptographer, can create an algorithm that he himself can't break.", Author = "Bruce Schneier" },
        new Quote { Id = "https://en.wikiquote.org/wiki/A_Song_of_Ice_and_Fire", Text = "A knight who remembered his vows.", Author = "A Song of Ice and Fire" },
        new Quote { Id = "https://en.wikiquote.org/wiki/The_Curse_of_the_Jade_Scorpion", Text = "I hate her just like I hate that German chancellor with the mustache.", Author = "The Curse of the Jade Scorpion" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Dehab_Faytinga", Text = "There were many Kunama and Nara girls that joined the armed struggle. Many of them were small girls and they were taken there to get education and my assignment was to help them as a translator and provide them political training in their language. I stayed there for about six months.", Author = "Dehab Faytinga" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Muslim_chronicles_for_Indian_history", Text = "The chronicles unfortunately do not portray the culture of the ghazis; they give detailed descriptions of battles, but cultural information is confined to the rulers and their courts.", Author = "Muslim chronicles for Indian history" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Grace_Nkansa_Asante", Text = "God has been good. I didn’t even know about this feat. And now everybody is celebrating me. And I’m very grateful to all my loved ones. It was hard to combine a lot of this with my academic work and my colleagues were supportive and understood me", Author = "Grace Nkansa Asante" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Douglas_John_Hall", Text = "Princeton Lectures on Youth, Church, and Culture", Author = "Douglas John Hall" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Kozan_Ikky%C5%8D", Text = "Empty-handed I entered the worldBarefoot I leave it.My coming, my going -Two simple happeningsThat got entangled.", Author = "Kozan Ikkyō" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Elijah", Text = "As the Lord God of Israel liveth, before whom I stand, there shall not be dew nor rain these years, but according to my word.", Author = "Elijah" },
        new Quote { Id = "https://en.wikiquote.org/wiki/John_Galsworthy", Text = "The world's a fine place for those who go out to take it; there's lots of unknown stuff in it yet. I'll fill your lap, my pretty, so full of treasures that you shan't know yourself. A man wasn't meant to sit at home...", Author = "John Galsworthy" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Mohammad_Habib", Text = "The Quranic conception of God was, and can still be, a revolutionary force of incalculable value for the attainment of human welfare.", Author = "Mohammad Habib" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Blessing_Onuh", Text = "The banks attacked include IBTC, Zenith, UBA, and First Bank. Several people were killed on the bank premises and many others sustained gunshot injuries.", Author = "Blessing Onuh" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Entity", Text = "It's been a thrilling journey — I have had to really learn that an orchestra is an entity — it's a creature. I have been calling it the dragon and the conductor is the dragon tamer. And you just have to... ride and don't let go and you will be fine.", Author = "Entity" },
        new Quote { Id = "https://en.wikiquote.org/wiki/2004_Indian_Ocean_earthquake_and_tsunami", Text = "This (disaster) is one of the greatest opportunities God has given us to share his love with people.", Author = "2004 Indian Ocean earthquake and tsunami" },
        new Quote { Id = "https://en.wikiquote.org/wiki/J%C3%A1nos_%C3%81der", Text = "We truly wish that a state so important for us should further develop in peace and stability. We wish to see Ukraine offer a secure and attractive future to all its citizens and that the Hungarian community feels at home in that country. To meet those goals we stand ready to provide all assistance.", Author = "János Áder" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Len_R._Troncale", Text = "There is a need to make general systems theory more user friendly.", Author = "Len R. Troncale" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Abdul_Sattar_Edhi", Text = "I always say, be human and preach humanity. I started my humanitarian service by strictly observing four principles: truth, simplicity, hard-work and punctuality, and I repeat, be human, preach humanity and adopt humanity.", Author = "Abdul Sattar Edhi" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Soul_%282020_film%29", Text = "Music is all I think about. From the moment I wake up in the morning... to the moment I fall asleep at night. I was born to play. It's my reason for living.", Author = "Soul (2020 film)" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Nakamura_Kichiemon_II", Text = "When you discard yourself, real love comes into relief.", Author = "Nakamura Kichiemon II" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Amy_Hempel", Text = "I would like to go for a ride with you, have you take me to stand before a river in the dark where hundreds of lightning bugs blink this code in sequence: right here, nowhere else! Right now, never again!", Author = "Amy Hempel" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Spencer_Tracy", Text = "Know your lines and don't bump into the furniture.", Author = "Spencer Tracy" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Nana_Ekua_Brew-Hammond", Text = "Don’t fall into the trap of feeling sorry for yourself because you haven’t yet got to the stage where you can [pursue your dream] full time", Author = "Nana Ekua Brew-Hammond" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Nancy_Bird_Walton", Text = "Other women who flew were women of independent means. But I had to do something with it.", Author = "Nancy Bird Walton" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Gianroberto_Casaleggio", Text = "Behind Gianroberto Casaleggio there is only Gianroberto Casaleggio. An ordinary citizen who, with his work and his (limited) resources, seeks, without any public or private funding, perhaps deluding himself, sometimes even making mistakes, to improve the society in which he lives.", Author = "Gianroberto Casaleggio" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Alidu_Seidu", Text = "It's a huge honour to have extended my contract with the club and to be continuing this great adventure. I'm delighted. I'd like to thank everyone who has helped me feel good at Rennes, the staff, the directors and my team-mates. I'd also like to thank the fans, who are always there.", Author = "Alidu Seidu" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Frank_Deford", Text = "I grew up in Baltimore and that's why I root for the Orioles. I'm very suspicious of people who move and take on a new team. You should stick with the team of your youth all the way to your grave. That shows a sense of loyalty and devotion.", Author = "Frank Deford" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Francis_Xavier_DiLorenzo", Text = "The love of Jesus Christ is the most powerful weapon against hatred. Only the light of Christ can quench the torches of hatred and violence. Let us pray for peace.", Author = "Francis Xavier DiLorenzo" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Buzz_Dixon", Text = "What can be taught in the school isn’t even as important as the connections you make. College gets you to meet likeminded people who will be in the same career as you. You meet someone who knows someone and you can work your way into writing a script or a novelization of a movie.", Author = "Buzz Dixon" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Seventh_Doctor", Text = "The Doctor: You don't understand regeneration, Mel. It's a lottery, and I've drawn the short plank.", Author = "Seventh Doctor" },
        new Quote { Id = "https://en.wikiquote.org/wiki/The_Prestige_%28film%29", Text = "Are you watching closely?", Author = "The Prestige (film)" },
        new Quote { Id = "https://en.wikiquote.org/wiki/The_Abyss", Text = "When it comes to the safety of these people, there's me and then there's God, understand?", Author = "The Abyss" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Thomas_de_Maizi%C3%A8re", Text = "A part of these answers would make the population feel unsafe.", Author = "Thomas de Maizière" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Mavis_Moyo", Text = "I will go and talk to the experts and we will teach you how to make oil on radio.", Author = "Mavis Moyo" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Lodi_dynasty", Text = "According to Abdullah, the Sultan plundered Nimsar Misrik in Hardoi district and depopulated it of all riff-raff and undesirable elements.", Author = "Lodi dynasty" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Jodie_Underhill", Text = "Today Waste Warriors has several projects working across tourist destinations in Himachal Pradesh. My heart will always lie in the Dharamshala but that project has reached a very difficult point,", Author = "Jodie Underhill" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Guire_Poulard", Text = "We urgently need to put order in the administration in Haiti, if the country were well organized in ten years it would be rebuilt.", Author = "Guire Poulard" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Karl_Hess", Text = "I would remind you that extremism in the defense of liberty is no vice.And let me remind you also that moderation in the pursuit of justice is no virtue.", Author = "Karl Hess" },
        new Quote { Id = "https://en.wikiquote.org/wiki/August_Spies", Text = "Can any one feel any respect for a government that accords rights only to the privileged classes, and none to the workers?", Author = "August Spies" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Shina_Peller", Text = "There is no leadership when there is no vision.", Author = "Shina Peller" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Patrick_McGoohan", Text = "Mel [Gibson] will always be Mad Max, and me, I will always be a number.", Author = "Patrick McGoohan" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Maria_Khan", Text = "I had the opportunity to go to Saudi before the influx of investment into the women’s game", Author = "Maria Khan" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Cheng_Wen-tsan", Text = "I hope the public can calm down and use dialogue instead of violence (opponents of pension reform who allegedly broke two of his ribs).", Author = "Cheng Wen-tsan" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Rollo_May", Text = "Anxiety is an even better teacher than reality, for one can temporarily evade reality by avoiding the distasteful situation; but anxiety is a source of education always present because one carries it within.", Author = "Rollo May" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Charles_Ndukauba", Text = "The suppression of citizens' right to assemble and voice their concerns hampers the democratic ideals the country aspires to uphold.", Author = "Charles Ndukauba" },
        new Quote { Id = "https://en.wikiquote.org/wiki/A_Star_Is_Born_%281954_film%29", Text = "[seeing Norman drunk] Mr. Maine is feeling no pain!", Author = "A Star Is Born (1954 film)" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Sharon_Ezeamaka", Text = "The only thing that can limit you is yourself at the end of the day.", Author = "Sharon Ezeamaka" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Francisco_Robles_Ortega", Text = "The witness of the martyrs should not only amaze us, the testimony of the martyrs should move us, it should be an invitation to us.", Author = "Francisco Robles Ortega" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Duck_and_Cover_%28film%29", Text = "It's a bomb! Duck and cover!", Author = "Duck and Cover (film)" },
        new Quote { Id = "https://en.wikiquote.org/wiki/I_Think_We%27re_All_Bozos_on_This_Bus", Text = "Geez, I'm standing here like an idiot, talking to myself. Might as well walk over to the old yellow line and stand here on the yellow line like an idiot, talking to myself.", Author = "I Think We're All Bozos on This Bus" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Animula_vagula_blandula", Text = "Animula vagula blandula, hospes comesque corporis, quae nunc abibis in loca, pallidula, rigida, nudula, nec ut soles dabis iocos?", Author = "Animula vagula blandula" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Beth_Mead", Text = "Yeah, we’re in the 21st century now – whoever you fall in love with, that’s OK as long as you’re happy.", Author = "Beth Mead" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Michael_Harris_%28mathematician%29", Text = "Langlands and Grothendieck are both (at least) Giants by any measure, and both were consciously successors of Galois.", Author = "Michael Harris (mathematician)" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Porcupine", Text = "I'm a little hoarse tonight. I've been living in Chicago for the past two months, and you know how it is, yelling for help on the way home every night. Things are so tough in Chicago that at Easter time, for bunnies the little kids use porcupines.", Author = "Porcupine" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Charles_Francis_Adams%2C_Sr.", Text = "In this country … men seem to live for action as long as they can and sink into apathy when they retire.", Author = "Charles Francis Adams, Sr." },
        new Quote { Id = "https://en.wikiquote.org/wiki/Insurgent_%28novel%29", Text = "One choice can destroy you", Author = "Insurgent (novel)" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Susie_Wiles", Text = "He’s a different person than he was.", Author = "Susie Wiles" },
        new Quote { Id = "https://en.wikiquote.org/wiki/The_Game_of_Death_%281972%29", Text = "Do you understand? This sword becomes a whip!", Author = "The Game of Death (1972)" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Edward_P._King", Text = "Tell General Wainwright that I have decided to surrender Bataan. This decision is solely my own, no member of my staff nor of my command has helped me to arrive at this decision. In my opinion, if I do not surrender to the Japanese, Bataan will be known as the greatest slaughter in history.", Author = "Edward P. King" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Ana-Maria_Henao-Restrepo", Text = "La cooperación de la comunidad científica en los últimos años ha mejorado y continúa evolucionando: es una batalla sin fin, y cuanto más estemos dispuestos a aprender de lo que hemos vivido, mejor será para todos en el planeta.", Author = "Ana-Maria Henao-Restrepo" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Helmut_F._Kaplan", Text = "Everything the Nazis did to Jews we are today practicing on animals. Our grandchildren will ask us one day: Where were you during the Holocaust of the animals? What did you do against these horrifying crimes? We won't be able to offer the same excuse for the second time, that we didn't know.", Author = "Helmut F. Kaplan" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Howard_Raiffa", Text = "Ideas are incestuous.", Author = "Howard Raiffa" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Ahmed_Djemal", Text = "I shall not return to Constantinople until I have conquered Egypt!", Author = "Ahmed Djemal" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Mikhail_Baryshnikov", Text = "You ask me what's happened in my life, why and how I did this and that. And I think and tell, but it's never true story, because everything is so much more complicated, and also I can't even remember how things happened. Whole process is boring. Also false, but mostly boring.", Author = "Mikhail Baryshnikov" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Diana_Rigg", Text = "Becoming a sex symbol overnight [in The Avengers] shocked me. I didn’t know how to handle it and I kept all the unopened fan mail in the boot of my car because I didn't know how to respond and thought it was rude to throw it away.", Author = "Diana Rigg" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Hot_Shots%21_Part_Deux", Text = "These men have taken a supreme vow of celibacy, like their fathers, and their fathers before them...", Author = "Hot Shots! Part Deux" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Esther_Lungu", Text = "God is great, and He is our foundation! I will stand firm! We have never taken anything that isn’t ours, and God is aware of this.", Author = "Esther Lungu" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Aurora_%28singer%29", Text = "My fans see me as an angel, but I'm not an angel. I'm just a normal person from Norway who writes music. They expect from me what I expect from them. They would be surprised if I was ever mean or inappropriate, but I want to be a good role model. You become that immediately when you get fans.", Author = "Aurora (singer)" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Lynn_Compton", Text = "The life I've led has only been made possible because I'm an American. The astounding people I've met along the way, the astonishing experience I've had, and the amazing opportunities I've been given have far exceeded anything I could have ever hoped for or expected.", Author = "Lynn Compton" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Nana_Aba_Appiah_Amfo", Text = "It’s a combination of hard work, identifying opportunities and taking advantage of those opportunities, and some favour from God that makes great.", Author = "Nana Aba Appiah Amfo" },
        new Quote { Id = "https://en.wikiquote.org/wiki/George_W._Bush", Text = "You know, I could run for governor and all this but I'm basically a media creation. I've never really done anything. I've worked for my dad. I worked in the oil industry. But that's not the kind of profile you have to have to get elected to public office.", Author = "George W. Bush" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Luddite", Text = "As the liberty lads o'er the seaBought their freedom, and cheaply, with blood,So we, boys, weShall die fighting or live free,And down with all kings but King Ludd!", Author = "Luddite" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Sidi_Yaqub", Text = "Sidi Yaqut of Janjira or Zanjira, once took a Maratha fort and seven hundred persons came out. Notwithstanding his word to grant quarter to the garrison he made the children and pretty women slaves, and forcibly converted them to Islam… but the men he put to death.", Author = "Sidi Yaqub" },
        new Quote { Id = "https://en.wikiquote.org/wiki/American_Israel_Public_Affairs_Committee", Text = "The friendship between Israel and the United States is a great asset to our country. And AIPAC is a great advocate for this vital relationship.", Author = "American Israel Public Affairs Committee" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Liu_Wen_%28model%29", Text = "I hope that when people see Asian women, they realize we are all different. A lot of time with Caucasian people, they just group us together as Asian. But even with different cities in China, people have different personalities.... We look Asian, but we still look different. We don't look the same.", Author = "Liu Wen (model)" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Jean-Baptiste-Charles-Marie_de_Beauvais", Text = "Le silence du peuple est la leçon des rois.", Author = "Jean-Baptiste-Charles-Marie de Beauvais" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Jos%C3%A9_Cabantan", Text = "There will never be peace and justice until we know justice and peace in our hearts.", Author = "José Cabantan" },
        new Quote { Id = "https://en.wikiquote.org/wiki/V._V._S._Laxman", Text = "The reason why Indian bowling has done exceptionally well in this World Cup is MS Dhoni. When we wrote them off, he kept supporting them. When they were struggling, only he was standing by his bowlers.", Author = "V. V. S. Laxman" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Pauline_Peyraud-Magnin", Text = "In my opinion, one of the major things that’s so attractive about women’s football, especially for the fans, is how approachable we are. We always take time at the end of the games to take pictures with the fans, sign autographs and chat with them.", Author = "Pauline Peyraud-Magnin" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Ruth_Rigoga", Text = "It is a long story but my whole life has been about sports. I tried playing very many games as I grew up, especially football. I studied high school on scholarship because of playing football,", Author = "Ruth Rigoga" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Susan_Howatch", Text = "A rational disposition must necessarily preclude a romantic outlook in life, and only the failures of this world can afford to dispense with a rational disposition.", Author = "Susan Howatch" },
        new Quote { Id = "https://en.wikiquote.org/wiki/J._R._Moehringer", Text = "Beer is amazing. Nutritional. Medicinal. A beverage, but also a meal.", Author = "J. R. Moehringer" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Michele_Serros", Text = "I understand that many people believe that writers write from their heart or from their soul. I write from the nagging pit of my gut, to make the stomachache go away.", Author = "Michele Serros" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Rights", Text = "The denial of God conduced to the denial of God-given rights – and that, in turn, conduced to rights becoming eminently alienable whenever it served the purposes of the government.", Author = "Rights" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Ennio_Antonelli", Text = "The family is the most efficient school of humanity of Christian life, transmitting human and Christian values in its own peculiar manner, based on example and testimony, on experience and daily life.", Author = "Ennio Antonelli" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Irma_Stern", Text = "Searching, I roamed the world—to arrive at the origin—at beauty—at truth—away from the lies of everyday—and my longing was burning hot—then the darkness opened up and I stood at the source of the Beginning—Paradise.", Author = "Irma Stern" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Frank_R._Wallace", Text = "From China to America to Mecca, forget mandates from Heaven, Jesus, or God. They do not exist. An a-priori mandate, however, does exist from metaphorical Zons here on Earth and across the cosmos.", Author = "Frank R. Wallace" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Charles_Lee_Isbell_Jr", Text = "I’m energized by this chance to serve the citizens of Illinois and advance the mission of learning, discovery, engagement and economic development", Author = "Charles Lee Isbell Jr" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Aneirin", Text = "Three hundred men hastened forth, wearing gold torques, defending the land – and there was slaughter. Though they were slain they slew, and they shall be honoured to the end of the world; and of all us kinsmen who went, alas, but for one man none escaped.", Author = "Aneirin" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Celina_Benavidez", Text = "She built an extensive network of personal and professional influential contacts across the United States.", Author = "Celina Benavidez" },
        new Quote { Id = "https://en.wikiquote.org/wiki/One_of_Our_Aircraft_Is_Missing", Text = "Do you think that we Hollanders, who threw the sea out of our country, will let the Germans have it? Better the sea.", Author = "One of Our Aircraft Is Missing" },
