        new Quote { Id = "https://en.wikiquote.org/wiki/Music", Text = "To me, the wonderful thing about music is a love affair between the performer and the composer, and between the composer and his audience. This love affair is a tripartite thing.", Author = "Music" },
        new Quote { Id = "https://en.wikiquote.org/wiki/George_Sewell_%28physician%29", Text = "When all the Blandishments of Life are gone,The Coward sneaks to Death, the Brave live on.", Author = "George Sewell (physician)" },
        new Quote { Id = "https://en.wikiquote.org/wiki/The_Texas_Chainsaw_Massacre%3A_The_Beginning", Text = "People may not remember what we say here tonight, but by God they'll remember what we did.", Author = "The Texas Chainsaw Massacre: The Beginning" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Time_Enough_for_Love", Text = "History has the relation to truth that theology has to religion — i.e., none to speak of.", Author = "Time Enough for Love" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Gentlemen_of_Fortune", Text = "My job is to raise children, not to run around the Soviet Union with your crooks.", Author = "Gentlemen of Fortune" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Keith_Kellogg", Text = "He [Vladimir Putin] considers this a proxy war by NATO as well right now, and frankly, in a way, it is.", Author = "Keith Kellogg" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Jean-Pierre_Lehmann", Text = "The great pre-Christian civilizations of Greece and Rome had no religious wars and had a far healthier view of their frolicking gods and goddesses than the intolerant monotheistic Christianity that later came to dominate Europe.", Author = "Jean-Pierre Lehmann" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Dolores_O%27Riordan", Text = "I'm a strong-minded woman, but I don't try to deny that I'm a female in any way.", Author = "Dolores O'Riordan" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Hugh_Blair", Text = "What we call human reason, is not the effort or ability of one, so much as it is the result of the reason of many, arising from lights mutually communicated, in consequence of discourse and writing.", Author = "Hugh Blair" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Robert_Barry", Text = "I try to deal with things that maybe other people haven't thought about, emptiness, making a painting that isn't a painting. For years people have been concerned with what goes on inside the frame. Well maybe there is something going on outside the frame that could be considered an artistic idea.", Author = "Robert Barry" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Asa_Akira", Text = "Whenever I quit porn, I'll be starting at square one again—I am going to be where all my friends were ten years ago. I don't know if I want to have kids, so that is a huge issue right now in my mind, too...", Author = "Asa Akira" },
