        new Quote { Id = "https://en.wikiquote.org/wiki/Nahum_Rabinovitch", Text = "It is important to emphasize that not grappling with this problem will not make it disappear but rather will perpetuate the destruction of the unity and sanctity of the people, and that the new courts are working 100% according to halacha", Author = "Nahum Rabinovitch" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Lucy_Peacock_%28actress%29", Text = "I'm a very disciplined actor, but I also believe in kicking back and having a glass of wine.", Author = "Lucy Peacock (actress)" },
