        new Quote { Id = "https://en.wikiquote.org/wiki/Anacharsis", Text = "These decrees of yours are no different from spiders' webs. They'll restrain anyone weak and insignificant who gets caught in them, but they'll be torn to shreds by people with power and wealth.", Author = "Anacharsis" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Better_Off_Dead_%28film%29", Text = "Gee, I'm really sorry your mom blew up, Ricky. Doctor says she'll be okay, but she won't be able to eat any spicy foods for awhile.", Author = "Better Off Dead (film)" },
