        new Quote { Id = "https://en.wikiquote.org/wiki/Sally_Field", Text = "I haven't had an orthodox career, and I've wanted more than anything to have your respect. The first time I didn't feel it, but this time I feel it, and I can't deny the fact that you like me, right now, you like me!", Author = "Sally Field" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Pope_Francis", Text = "The unjust distribution of goods persists, creating a situation of social sin that cries out to Heaven and limits the possibilities of a fuller life for so many of our brothers.", Author = "Pope Francis" },
