        new Quote { Id = "https://en.wikiquote.org/wiki/The_Columbian_Orator", Text = "To scatter the clouds of ignorance and error from the atmosphere of reason; to remove the film of prejudice from the mental eye; and thus to irradiate the benighted mind with the cheering beams of truth, is at once the business and the glory of eloquence.", Author = "The Columbian Orator" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Maxwell_Maltz", Text = "There is within each of us a life-instinct, which is forever working toward health, happiness, and all that makes for more life for the individual.", Author = "Maxwell Maltz" },
