        new Quote { Id = "https://en.wikiquote.org/wiki/Social_Security_%28United_States%29", Text = "Now, Social Security through the years, for many many people, has been a terrible investment. It's really a tax, that's all it is. Social Security is a tax.", Author = "Social Security (United States)" },
