        new Quote { Id = "https://en.wikiquote.org/wiki/Carole_King", Text = "I'm a songwriter first, have always been, and probably always will be. Making the demo is a natural product of writing a song; after that, I'm happy to hear other people do it in other ways.", Author = "Carole King" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Agostino_Giuseppe_Delfino", Text = "In a country that is still being plagued by civil unrest and where the government is weak, the Catholic Church has a great moral authority due to its social commitment, especially in the sectors of healthcare and education.", Author = "Agostino Giuseppe Delfino" },
