        new Quote { Id = "https://en.wikiquote.org/wiki/Mona_Mostafa_Mohamed", Text = "We could not have created this lab without Dr. Sloane's assistance.", Author = "Mona Mostafa Mohamed" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Jeanne_Calment", Text = "I had to wait 110 years to become famous... I intend to enjoy it as long as possible.", Author = "Jeanne Calment" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Charles_Eastman", Text = "There was no religious ceremony connected with marriage among us, while on the other hand the relation between man and woman was regarded as in itself mysterious and holy.", Author = "Charles Eastman" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Kogaku_Soko", Text = "My final words are these:As I fall I throw all on a high mountain peak -Lo! All creation shatters; thus it isThat I destroy Zen doctrine.", Author = "Kogaku Soko" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Frantz_Fanon", Text = "We are nothing on earth if we are not in the first place the slaves of a cause, the cause of the peoples, the cause of justice and liberty.", Author = "Frantz Fanon" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Fr%C3%A9d%C3%A9ric_Bazille", Text = "The big classical compositions are finished; an ordinary view of daily life would be much more interesting.", Author = "Frédéric Bazille" },
        new Quote { Id = "https://en.wikiquote.org/wiki/William_Lenthall", Text = "May it please your majesty, I have neither eyes to see, nor tongue to speak, in this place, but as the house is pleased to direct me, whose servant I am here; and I humbly ask pardon that I cannot give any other answer to what your majesty is pleased to demand of me.", Author = "William Lenthall" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Ingram_Crockett", Text = "The splendor of Silence,—of snow-jeweled hills and of ice.", Author = "Ingram Crockett" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Gerard_Tlali_Lerotholi", Text = "Young people, he said, should not be postponed for the future: they are here now and the energy and the vibrancy that they show should be taken into account.", Author = "Gerard Tlali Lerotholi" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Blessings_%28novel%29", Text = "It’s one thing to love a child, but it’s an entirely different thing for the same child to feel loved. A home is the last place a child should feel conditionally loved.", Author = "Blessings (novel)" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Edmund_Sears", Text = "Death is a stage in human progress, to be passed as we would pass from childhood to youth, or from youth to manhood, and with the same consciousness of an everlasting nature.", Author = "Edmund Sears" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Albert_Lutuli", Text = "I do not hate the white man; you see, his position of domination has placed him in a position of moral weakness.", Author = "Albert Lutuli" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Jeannette_Kagame", Text = "It is our responsibility to teach our children about our history, so that they can know the path Rwanda has walked, the heroism, the strong spirit and humility that defines us", Author = "Jeannette Kagame" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Irony", Text = "'Twas thine own genius gave the final blow, And help'd to plant the wound that laid thee low: So the struck eagle, stretch'd upon the plain,No more through rolling clouds to soar again,View'd his own feather on the fatal dart,And wing'd the shaft that quiver'd in his heart.", Author = "Irony" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Edwin_Vincent_O%27Hara", Text = "The fact remains that the Catholic home is the great nursery of faith. Religion is engaged in the work of character forming and childhood is the period of character formation. The stronghold of childhood must then be the citadel of the Church's hope.", Author = "Edwin Vincent O'Hara" },
        new Quote { Id = "https://en.wikiquote.org/wiki/American_robin", Text = "Yes, the robin, the Opechee,Joyous said, O Chibiabos,Teach me tones as sweet and tender,Teach me songs as full of gladness!", Author = "American robin" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Persona_%281966_film%29", Text = "I don't know what to say, Doctor. First her face looks soft, almost childish. Then you see her eyes... She's got such a severe look, I think.", Author = "Persona (1966 film)" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Antonia_Wright_%28artist%29", Text = "The day I decided to commit to being an artist was one of the best days of my life. I knew what I loved to do and what I now had to do. Although it was a totally frightening career choice, it was also one of the most liberating.", Author = "Antonia Wright (artist)" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Mourine_Osoru", Text = "I want to tackle youth unemployment in my district by establishing small income- generating projects.", Author = "Mourine Osoru" },
        new Quote { Id = "https://en.wikiquote.org/wiki/William_Playfair", Text = "Men in general are very slow to enter into what is reckoned a new thing; and there seems to be a very universal as well as great reluctance to undergo the drudgery of acquiring information that seems not to be absolutely necessary.", Author = "William Playfair" },
        new Quote { Id = "https://en.wikiquote.org/wiki/The_Bible_and_violence", Text = "Genesis 6:11: the earth was corrupt in God's sight, and the earth was filled with violence.", Author = "The Bible and violence" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Paul_Eusebius_Mea_Kaiuea", Text = "As Jesus was the leading force of evangelization to his disciples, so the Bishop must be a leading force of evangelization in his own diocese and encourage all the priests, sisters, brothers and lay people to take an active role in the mission of evangelization.", Author = "Paul Eusebius Mea Kaiuea" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Olivette_Otele", Text = "You are right to believe in the goodness of people. Keep doing what you do; working hard, loving, laughing, forgiving and doing your bit might not change the whole world, but it will change you for the best.", Author = "Olivette Otele" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Chimamanda_Ngozi_Adichie", Text = "The problem with gender is that it prescribes how we should be rather than recognising how we are. Now imagine how much happier we would be, how much freer to be our true individual selves if we didn't have the weight of gender expectations.", Author = "Chimamanda Ngozi Adichie" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Ward_Cunningham", Text = "Why have a locked wiki when you can instead just post static Web pages?", Author = "Ward Cunningham" },
        new Quote { Id = "https://en.wikiquote.org/wiki/D._D._Raphael", Text = "Justice, like Janus, has two faces, one conservative, the other reformative. These two faces are apparent both in the law and in the thought of social and political ethics.", Author = "D. D. Raphael" },
        new Quote { Id = "https://en.wikiquote.org/wiki/The_Strange_Woman", Text = "I wanted so many things. I wanted the whole world, but... it was really only you!", Author = "The Strange Woman" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Jorge_Guill%C3%A9n", Text = "Cuánto gozo a la flor dejaPreciosamente la abeja!", Author = "Jorge Guillén" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Gladys_Kokorwe", Text = "Government alone cannot succeed. It is through efforts such as these that many dreams can be realised. I cannot express my happiness at the success of such a tournament because it does not only bring people together but it also helps expose the talent that we have.", Author = "Gladys Kokorwe" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Angel_Eyes_%28film%29", Text = "Then I realized that it doesn't have to be perfect... It can be whatever it is.", Author = "Angel Eyes (film)" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Tjawangwa_Dema", Text = "I studied in Botswana and in the classroom it was the reading of stories that drew me to language, not poetry specifically.", Author = "Tjawangwa Dema" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Con_Air", Text = "They somehow managed to get every freak and creep in the universe on this one plane, and then somehow managed to let them take it over, and then they somehow managed to stick us right smack in the middle.", Author = "Con Air" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Raja_Chelliah", Text = "A sound anti-poverty strategy should not only aim to increase incomes, but also provide the poor with a variety of assets — personal, social, political and environmental to help them overcome human poverty.", Author = "Raja Chelliah" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Expend4bles", Text = "Conversation? Sounds more like angry chatter.", Author = "Expend4bles" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Ricky_Hatton", Text = "There were lots of celebrities at my fight. I heard through the grapevine Michael Caine was one...and not a lot of people know that!", Author = "Ricky Hatton" },
        new Quote { Id = "https://en.wikiquote.org/wiki/American_Splendor_%28film%29", Text = "I've had enough bad experiences and growth to last me plenty...Right now, I'd be glad to trade some growth for happiness.", Author = "American Splendor (film)" },
        new Quote { Id = "https://en.wikiquote.org/wiki/The_Story_of_Saiunkoku", Text = "A woman's word is a promise.", Author = "The Story of Saiunkoku" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Andr%C3%A9-Marie_Amp%C3%A8re", Text = "Écoute les savants, mais ne les écoute que d'une oreille!... Que l'autre soit toujours prête à recevoir les doux accents de la voix de ton ami céleste!", Author = "André-Marie Ampère" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Travis_Tritt", Text = "When Tritt came along, he quickly became Waylon Jennings’ favorite new artist. Is there a bigger compliment?", Author = "Travis Tritt" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Christopher_Lasch", Text = "If elites speak only to themselves, one reason for this is the absence of institutions that promote general conversation across class lines. Civic life requires settings in which people meet as equals, without regard to race, class, or national origins.", Author = "Christopher Lasch" },
        new Quote { Id = "https://en.wikiquote.org/wiki/In_Cold_Blood_%28film%29", Text = "Doctors. They made a dwarf out of me. Doctors and lawyers. What do they care? Ever see a millionaire fry in the electric chair? Hell, no. There's two kinds of laws, honey: One for the rich and one for the poor.", Author = "In Cold Blood (film)" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Tabitha_and_Napoleon_D%27umo", Text = "Let other dance styles inspire and influence your own and remember that there are no boundaries. Dare to be original.", Author = "Tabitha and Napoleon D'umo" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Ken_Kutaragi", Text = "PlayStation 3 will be capable running games at 120 fps.", Author = "Ken Kutaragi" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Firhad_Hakim", Text = "Those who are not born in Islam are unfortunate! They are born with misfortune. We have to bring them under the fold of Islam. We need to spread Islam among non-Muslims. If we can bring someone on the path of Islam, then, we will prove to be true Muslims.", Author = "Firhad Hakim" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Karl_Brandt", Text = "Ethical obligation has to subordinate itself to the totalitarian nature of war.", Author = "Karl Brandt" },
        new Quote { Id = "https://en.wikiquote.org/wiki/George_Best", Text = "If you'd given me the choice of going out and beating four men and smashing a goal in from thirty yards against Liverpool or going to bed with Miss World, it would have been a difficult choice. Luckily, I had both.", Author = "George Best" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Thomas_James_Conaty", Text = "Two thoughts seemed to dominate his life—religion and patriotism; thoughts which form the basis of every true life", Author = "Thomas James Conaty" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Harry_J._Gensler", Text = "Metaethics is more basic, since it studies how to select moral principles and thus how to do normative ethics.", Author = "Harry J. Gensler" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Georges_de_Scud%C3%A9ry", Text = "La victoire me suit, et tout suit la victoire.", Author = "Georges de Scudéry" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Robert_Maxwell", Text = "I can't get on with men [...] or perhaps it might be truer to say that they can't get on with me. They were not very friendly in the Commons, I suppose it was because I was a bit brash; in fact I know I was. I was impatient with the slow archaic procedure.", Author = "Robert Maxwell" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Piers_Anthony", Text = "I found that I simply couldn't take fantasy seriously, so it became humourous, and continued from there. I turned my home state of Florida into the Land of Xanth.", Author = "Piers Anthony" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Echo", Text = "Let echo, too, perform her part,Prolonging every note with art;And in a low expiring strain,Play all the comfort o'er again.", Author = "Echo" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Antonio_Yapsutco_Fortich", Text = "For them, I shall continue to pray that the light of Christ´s love will someday touch them so that we will become friends once more.", Author = "Antonio Yapsutco Fortich" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Robert_Fulghum", Text = "I believe that imagination is stronger than knowledge — That myth is more potent than history. I believe that dreams are more powerful than facts —That hope always triumphs over experience — That laughter is the only cure for grief. And I believe that love is stronger than death.", Author = "Robert Fulghum" }
    };
}